window.PLACES=[{"id":0,"name":"Raan Jay Fai","g":"food","category":"street-food","area":"Old Town (Phra Nakhon)","lat":13.75265,"lng":100.50462,"vibe":"Michelin-starred street stall where a woman in ski goggles cooks crab omelettes over roaring charcoal","tip":"Walk-in only, so queue early. She hinted at retiring in 2024 and then denied it, so check before you go. Pricey crab omelette","price":"฿฿฿","hours":"Roughly Wed–Sat 9am–7pm","date_friendly":true,"night":false,"tags":["michelin","legendary","street-food","queue"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/","https://thethaiger.com/news/national/michelin-chef-jay-fai-cooks-up-clarity-im-not-closing-my-restaurant-video"],"coord_confidence":"high"},{"id":1,"name":"Thipsamai Pad Thai","g":"food","category":"street-food","area":"Old Town (Phra Nakhon)","lat":13.7529,"lng":100.50475,"vibe":"Bangkok's most famous pad thai since 1966, with woks flaming out front all night","tip":"Order the pad thai wrapped in egg and the fresh orange juice. The queue moves fast, so go after 9pm","price":"฿","hours":"Evenings until late","date_friendly":true,"night":true,"tags":["legendary","street-food","late-night"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"medium"},{"id":2,"name":"Mont Nom Sod","g":"cafe","category":"dessert","area":"Old Town (Dinso Rd)","lat":13.75468,"lng":100.50122,"vibe":"Retro milk bar from 1964 serving charcoal-toasted bread with pandan custard and fresh milk","tip":"Get the steamed bread with sangkaya custard and a cold glass of milk. Good stop after Democracy Monument","price":"฿","hours":"~2pm–11pm","date_friendly":true,"night":true,"tags":["retro","dessert","old-school","local"],"sources":["https://littlebigreddot.com/yaowarat-after-dark-the-ultimate-top-5-street-food-spots-in-bangkoks-chinatown-2025/"],"coord_confidence":"medium"},{"id":3,"name":"Nuttaporn Ice Cream","g":"cafe","category":"dessert","area":"Old Town (Phraeng Phuthon)","lat":13.75337,"lng":100.4988,"vibe":"Tiny coconut-ice-cream shophouse from 1952, tucked in a restored old-town square","tip":"Coconut ice cream with sticky rice toppings. Wander Phraeng Phuthon's heritage shophouses after","price":"฿","hours":"Daytime","date_friendly":true,"night":false,"tags":["heritage","dessert","hidden"],"sources":[],"coord_confidence":"medium"},{"id":4,"name":"Methavalai Sorndaeng","g":"food","category":"restaurant","area":"Old Town (Democracy Monument)","lat":13.7568,"lng":100.5024,"vibe":"Old-school 1950s Thai dining room with a live band, like stepping into a Thai movie","tip":"Crispy river fish with chili sauce, crab yellow curry and coconut ice cream. Go for dinner when the band plays","price":"฿฿","hours":"Lunch & dinner","date_friendly":true,"night":true,"tags":["retro","live-music","michelin"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"medium"},{"id":5,"name":"Make Me Mango","g":"cafe","category":"dessert","area":"Tha Tien (near Wat Pho)","lat":13.7462,"lng":100.4927,"vibe":"All-mango dessert café in an old shophouse, a short walk from Wat Pho","tip":"Mango sticky rice and the mango shaved-ice platter. Good heat break after the temples","price":"฿","hours":"~10:30am–8pm","date_friendly":true,"night":false,"tags":["dessert","instagrammable","mango"],"sources":[],"coord_confidence":"medium"},{"id":6,"name":"Sala Rattanakosin Eatery & Bar","g":"food","category":"restaurant","area":"Riverside (Tha Tien)","lat":13.7451,"lng":100.4911,"vibe":"Glass-walled dining room facing Wat Arun across the river, with a rooftop bar for sunset","tip":"Book a window table around sunset. Try the soft-shell crab, then move up to the rooftop","price":"฿฿฿","hours":"Lunch & dinner","date_friendly":true,"night":true,"tags":["view","wat-arun","sunset","rooftop"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"medium"},{"id":7,"name":"Supanniga Eating Room (Tha Tien)","g":"food","category":"restaurant","area":"Riverside (Tha Tien)","lat":13.7457,"lng":100.4908,"vibe":"Riverside shophouse cooking grandma-style Trat recipes, with Wat Arun glowing opposite","tip":"Moo chamuang and the crabmeat omelette. Reserve the upstairs terrace for sunset","price":"฿฿","hours":"Lunch & dinner","date_friendly":true,"night":true,"tags":["view","wat-arun","thai","sunset"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"medium"},{"id":8,"name":"Chom Arun","g":"food","category":"restaurant","area":"Riverside (Maha Rat Rd)","lat":13.7473,"lng":100.491,"vibe":"Rooftop tables staring straight at Wat Arun as it lights up at dusk","tip":"Book the 5pm slot about a month ahead to catch sunset and the lit temple. You come for the view, not the food","price":"฿฿","hours":"11am–3pm, 5pm–9:30pm","date_friendly":true,"night":true,"tags":["view","wat-arun","rooftop","sunset"],"sources":["https://www.trvlogue.com/en/bangkok-chom-arun-dinner-review"],"coord_confidence":"medium"},{"id":9,"name":"ViVi The Coffee Place","g":"cafe","category":"cafe","area":"Riverside (Tha Tien)","lat":13.7504,"lng":100.4888,"vibe":"Hidden riverside deck café at the end of an alley, with a front-row view of Wat Arun","tip":"Grab a deck seat in late afternoon. Cheap drinks and good sunset light","price":"฿","hours":"~10am–6pm","date_friendly":true,"night":false,"tags":["view","hidden","riverside","wat-arun"],"sources":["https://thailand.tripcanvas.co/bangkok/unique-cafes-restaurants/"],"coord_confidence":"medium"},{"id":10,"name":"Floral Café at Napasorn","g":"cafe","category":"cafe","area":"Pak Khlong Talat (Flower Market)","lat":13.7427,"lng":100.4974,"vibe":"Secret-garden café hidden above a flower shop in the 24-hour flower market","tip":"Go in the evening, then walk the flower market when it's busiest. Closed Sundays","price":"฿฿","hours":"Mon–Sat 10am–10pm","date_friendly":true,"night":true,"tags":["hidden","floral","instagrammable"],"sources":["https://thailand.tripcanvas.co/bangkok/unique-cafes-restaurants/","https://www.thatbangkoklife.com/unique-cafes-in-bangkok/"],"coord_confidence":"medium"},{"id":11,"name":"Steve Café & Cuisine (Dhevet)","g":"food","category":"restaurant","area":"Thewet / Dusit riverside","lat":13.7714,"lng":100.5007,"vibe":"Old wooden riverside house reached through winding alleys, serving homestyle Thai at sunset","tip":"Crispy catfish salad and tamarind duck. Sit on the deck at golden hour","price":"฿฿","hours":"Lunch & dinner","date_friendly":true,"night":true,"tags":["hidden","riverside","sunset","view"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"medium"},{"id":12,"name":"Lhong Tou Café","g":"cafe","category":"cafe","area":"Chinatown (Yaowarat)","lat":13.7414,"lng":100.5085,"vibe":"Chinese-style café with double-decker bunk seating and dim sum on Yaowarat Rd","tip":"Dim sum plus the Chinese tea drinks. Good warm-up before the Yaowarat street-food crawl","price":"฿","hours":"8am–10pm","date_friendly":true,"night":true,"tags":["themed","instagrammable","dim-sum"],"sources":["https://www.thatbangkoklife.com/unique-cafes-in-bangkok/","https://www.ladyironchef.com/tag/dim-sum-places-bangkok/"],"coord_confidence":"low"},{"id":13,"name":"Nai Ek Roll Noodles","g":"food","category":"street-food","area":"Chinatown (Yaowarat Soi 9)","lat":13.7421,"lng":100.5074,"vibe":"Chinatown institution for peppery rolled-noodle soup with ultra-crispy pork belly","tip":"Order kuay jab with crispy pork. It's open late, so make it your first stop on a night crawl","price":"฿","hours":"Until ~midnight","date_friendly":true,"night":true,"tags":["street-food","late-night","michelin-bib"],"sources":["https://www.remotelands.com/travelogues/eat-like-a-local-in-bangkoks-chinatown-at-these-6-street-eateries/"],"coord_confidence":"medium"},{"id":14,"name":"Kuay Jab Uan Pochana","g":"food","category":"street-food","area":"Chinatown (Yaowarat)","lat":13.7406,"lng":100.5103,"vibe":"Viral peppery kuay jab with a nightly queue down Yaowarat Rd","tip":"Order 'everything' with crispy pork. The queue is shortest after 10pm","price":"฿","hours":"Evenings–late","date_friendly":false,"night":true,"tags":["street-food","late-night","queue","viral"],"sources":["https://littlebigreddot.com/yaowarat-after-dark-the-ultimate-top-5-street-food-spots-in-bangkoks-chinatown-2025/","https://www.eatingthaifood.com/restaurants/kuay-jab/"],"coord_confidence":"low"},{"id":15,"name":"T&K Seafood","g":"food","category":"street-food","area":"Chinatown (Yaowarat x Phadung Dao)","lat":13.73985,"lng":100.51015,"vibe":"Green-shirted sidewalk seafood chaos on Chinatown's main corner, under the neon signs","tip":"Grilled river prawns and steamed lime sea bass. Sit streetside after 7pm for the full neon atmosphere","price":"฿฿","hours":"~4:30pm–1am","date_friendly":true,"night":true,"tags":["street-food","seafood","neon","late-night"],"sources":["https://littlebigreddot.com/yaowarat-after-dark-the-ultimate-top-5-street-food-spots-in-bangkoks-chinatown-2025/"],"coord_confidence":"medium"},{"id":16,"name":"Pa Tong Go Savoey","g":"cafe","category":"dessert","area":"Chinatown (Yaowarat)","lat":13.741,"lng":100.5095,"vibe":"Fried Thai-Chinese doughnuts dunked in pandan custard, a must-do on Yaowarat","tip":"Patonggo with green sangkaya dip. Share a bag while you walk the strip","price":"฿","hours":"Evenings","date_friendly":true,"night":true,"tags":["dessert","street-food","chinatown"],"sources":["https://littlebigreddot.com/yaowarat-after-dark-the-ultimate-top-5-street-food-spots-in-bangkoks-chinatown-2025/"],"coord_confidence":"low"},{"id":17,"name":"Potong","g":"food","category":"restaurant","area":"Chinatown (Vanich 1 Rd)","lat":13.7412,"lng":100.5059,"vibe":"Tasting menu in a 120-year-old family pharmacy shophouse, with a hidden rooftop bar","tip":"Book weeks ahead for the progressive Thai-Chinese menu. Have a drink at the top-floor bar first","price":"฿฿฿฿","hours":"Dinner","date_friendly":true,"night":true,"tags":["michelin","fine-dining","heritage","splurge"],"sources":[],"coord_confidence":"medium"},{"id":18,"name":"Mother Roaster","g":"cafe","category":"cafe","area":"Talat Noi","lat":13.7319,"lng":100.5127,"vibe":"Secret coffee bar up the stairs of an old car-parts garage, run by a coffee-obsessed auntie","tip":"Walk through the junk and climb upstairs. Try her signature brews. Daytime only","price":"฿","hours":"~9am–5pm","date_friendly":true,"night":false,"tags":["hidden","quirky","talat-noi"],"sources":["https://www.phuket101.net/bangkok/mother-roaster-talat-noi/","https://thesmartlocal.com/thailand/mother-roaster-bangkok"],"coord_confidence":"medium"},{"id":19,"name":"Such A Small World","g":"cafe","category":"cafe","area":"Talat Noi (Charoen Krung)","lat":13.7316,"lng":100.5132,"vibe":"Co-op video-game lounge with vinyl booths and free movies, hidden on a third floor","tip":"Book a private lounge (from ฿400) for a date night of retro games. Closed Mondays","price":"฿฿","hours":"Tue–Sun 12pm–10pm","date_friendly":true,"night":true,"tags":["themed","games","hidden","vinyl"],"sources":["https://thesmartlocal.com/read/themed-cafes-bangkok/"],"coord_confidence":"medium"},{"id":20,"name":"Prachak Roasted Duck","g":"food","category":"restaurant","area":"Bang Rak (Charoen Krung)","lat":13.7258,"lng":100.5145,"vibe":"Roast-duck shophouse running since 1909, with glossy ducks hanging in the window","tip":"Roast duck and crispy pork over rice. Quick, cheap lunch on Old Charoen Krung","price":"฿","hours":"~8:30am–8:30pm","date_friendly":false,"night":false,"tags":["legendary","heritage","local"],"sources":[],"coord_confidence":"medium"},{"id":21,"name":"The Never Ending Summer","g":"food","category":"restaurant","area":"Khlong San (The Jam Factory)","lat":13.7295,"lng":100.5083,"vibe":"Moody modern-Thai dining room in a converted riverside warehouse, designed by a star architect","tip":"Book dinner, then stroll the Jam Factory courtyard and riverfront. Great first-date venue","price":"฿฿฿","hours":"Lunch & dinner","date_friendly":true,"night":true,"tags":["design","riverside","thai"],"sources":[],"coord_confidence":"medium"},{"id":22,"name":"Sirimahannop","g":"food","category":"restaurant","area":"Riverside (Asiatique)","lat":13.7045,"lng":100.5029,"vibe":"Drinks and seafood aboard a replica tall ship moored on the Chao Phraya","tip":"Sunset cocktails and oysters on deck. Book via Eatigo for deals, then walk Asiatique","price":"฿฿฿","hours":"Evenings","date_friendly":true,"night":true,"tags":["unique","view","riverside","ship"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"medium"},{"id":23,"name":"Unicorn Café","g":"cafe","category":"cafe","area":"Sathorn (Soi Sathorn 8)","lat":13.7225,"lng":100.5244,"vibe":"Pastel overload: rainbow food, unicorn plush forest and unicorn onesies you can rent","tip":"Rent a onesie (฿100) for ridiculous photos and order the rainbow crepe cake. Closed Mondays","price":"฿฿","hours":"Tue–Sun 12pm–8pm","date_friendly":true,"night":false,"tags":["themed","kitsch","instagrammable"],"sources":["https://thesmartlocal.com/read/themed-cafes-bangkok/","https://www.thatbangkoklife.com/unique-cafes-in-bangkok/"],"coord_confidence":"medium"},{"id":24,"name":"Ojo at The Standard Mahanakhon","g":"food","category":"restaurant","area":"Silom (King Power Mahanakhon)","lat":13.7235,"lng":100.528,"vibe":"Wildly colourful Mexican restaurant on the 76th floor of Bangkok's pixelated tower","tip":"Book a window table for sunset. Combine with the Mahanakhon glass-floor Skywalk","price":"฿฿฿฿","hours":"Dinner","date_friendly":true,"night":true,"tags":["view","rooftop","design","splurge"],"sources":[],"coord_confidence":"high"},{"id":25,"name":"Polo Fried Chicken (Gai Tod Jay Kee)","g":"food","category":"street-food","area":"Lumphini (Soi Polo)","lat":13.7308,"lng":100.5436,"vibe":"Cult fried chicken topped with a mountain of crispy garlic, served with som tam","tip":"Half chicken plus sticky rice. Eat in, then walk to Lumphini Park","price":"฿","hours":"~10am–9pm","date_friendly":true,"night":false,"tags":["street-food","michelin-bib","local"],"sources":[],"coord_confidence":"medium"},{"id":26,"name":"Sretsis Parlour","g":"cafe","category":"cafe","area":"Ploenchit (Central Embassy)","lat":13.7439,"lng":100.5468,"vibe":"Fairytale tea parlour from a Thai fashion label: pink, whimsical and very extra","tip":"Afternoon tea set (from ~฿550) works well for a cute daytime date","price":"฿฿฿","hours":"10am–8pm","date_friendly":true,"night":false,"tags":["themed","instagrammable","afternoon-tea"],"sources":["https://thailand.tripcanvas.co/bangkok/unique-cafes-restaurants/","https://www.thatbangkoklife.com/unique-cafes-in-bangkok/"],"coord_confidence":"high"},{"id":27,"name":"Aksorn","g":"food","category":"restaurant","area":"Chidlom (Central: The Original Store)","lat":13.7439,"lng":100.5439,"vibe":"David Thompson revives recipes from 1940s–60s Thai cookbooks, with golden-hour views","tip":"Book the set menu and ask about the cookbook behind each dish","price":"฿฿฿฿","hours":"Dinner","date_friendly":true,"night":true,"tags":["fine-dining","story","view"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"medium"},{"id":28,"name":"Mango Tango","g":"cafe","category":"dessert","area":"Siam Square","lat":13.7448,"lng":100.5339,"vibe":"The OG mango dessert spot, where everything is mango and the queues are full of Siam teens","tip":"Order the Mango Tango set (mango, pudding, ice cream, sticky rice) and share it","price":"฿","hours":"~12pm–10pm","date_friendly":true,"night":true,"tags":["dessert","mango","siam"],"sources":[],"coord_confidence":"medium"},{"id":29,"name":"Caturday Cat Café","g":"cafe","category":"cafe","area":"Ratchathewi","lat":13.7521,"lng":100.5324,"vibe":"Big, well-run cat café full of fluffy breeds, a short walk from BTS Ratchathewi","tip":"Weekday afternoons are calmer. Order a drink and follow the cat-handling rules","price":"฿฿","hours":"~10am–8pm","date_friendly":true,"night":false,"tags":["animal","cats","cute"],"sources":["https://www.outlooktraveller.com/experiences/food-and-drink/bizarre-bangkok-weird-cafes-to-visit","https://www.ladyironchef.com/2019/09/caturday-cat-cafe/"],"coord_confidence":"medium"},{"id":30,"name":"Victory Monument Boat Noodle Alley","g":"food","category":"street-food","area":"Victory Monument","lat":13.7658,"lng":100.5374,"vibe":"Canal-side alley of tiny boat-noodle bowls where people stack empties like trophies","tip":"Bowls are about ฿20 each. Order 5+ each and compete over who stacks more","price":"฿","hours":"~9am–8pm","date_friendly":true,"night":false,"tags":["street-food","local","challenge"],"sources":[],"coord_confidence":"medium"},{"id":31,"name":"Lay Lao","g":"food","category":"restaurant","area":"Ari","lat":13.7802,"lng":100.544,"vibe":"Breezy blue-and-white Isaan seafood spot in hip Ari, beloved by locals","tip":"Som tam with salted egg, grilled fish and sticky rice. Go before 7pm on weekends","price":"฿฿","hours":"Lunch & dinner","date_friendly":true,"night":true,"tags":["isaan","michelin-bib","ari"],"sources":[],"coord_confidence":"medium"},{"id":32,"name":"Big Dog Café","g":"cafe","category":"cafe","area":"Huai Khwang (Ratchada)","lat":13.778,"lng":100.574,"vibe":"Café full of huge, gentle dogs (Great Danes, Alaskans) in 2-hour play slots","tip":"Reserve a slot ahead. Mornings are less crowded","price":"฿฿","hours":"9am–10pm","date_friendly":true,"night":false,"tags":["animal","dogs","cute"],"sources":["https://thailand.tripcanvas.co/bangkok/unique-cafes-restaurants/","https://www.thatbangkoklife.com/unique-cafes-in-bangkok/"],"coord_confidence":"low"},{"id":33,"name":"Cabbages & Condoms","g":"food","category":"restaurant","area":"Sukhumvit (Soi 12)","lat":13.7385,"lng":100.5576,"vibe":"Garden restaurant decked out in condom art, where profits fund sexual-health charity","tip":"Fun icebreaker date. Get the green curry and tom yum, and you get condoms instead of mints","price":"฿฿","hours":"11am–10pm","date_friendly":true,"night":true,"tags":["quirky","concept","garden"],"sources":["https://www.outlooktraveller.com/experiences/food-and-drink/bizarre-bangkok-weird-cafes-to-visit","https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"high"},{"id":34,"name":"Haoma","g":"food","category":"restaurant","area":"Sukhumvit 31","lat":13.7372,"lng":100.5695,"vibe":"Zero-waste fine dining with vertical gardens, a fish tank and insect amuse-bouches","tip":"Book the tasting menu and ask for a garden tour","price":"฿฿฿฿","hours":"Dinner","date_friendly":true,"night":true,"tags":["sustainable","fine-dining","concept"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"medium"},{"id":35,"name":"Gaggan Anand","g":"food","category":"restaurant","area":"Sukhumvit 31","lat":13.7356,"lng":100.5658,"vibe":"Rock-and-roll theatre of 20+ courses with an emoji menu and dishes you lick off the plate","tip":"Book months ahead for the chef's-table experience. A once-in-a-trip splurge","price":"฿฿฿฿","hours":"Dinner","date_friendly":true,"night":true,"tags":["theatrical","fine-dining","splurge"],"sources":[],"coord_confidence":"low"},{"id":36,"name":"Mae Varee","g":"cafe","category":"dessert","area":"Thonglor","lat":13.7238,"lng":100.5856,"vibe":"Bangkok's most famous mango sticky rice stand, at the mouth of Thonglor","tip":"Grab a takeaway box of mango sticky rice and eat it on a stroll up Thonglor","price":"฿","hours":"~6am–10pm","date_friendly":true,"night":true,"tags":["dessert","mango","iconic"],"sources":[],"coord_confidence":"high"},{"id":37,"name":"The Blooming Gallery","g":"cafe","category":"cafe","area":"Thonglor (Eight Thonglor)","lat":13.731,"lng":100.5807,"vibe":"Café smothered in real flowers, doing high tea that looks like a bouquet","tip":"Afternoon tea for two. Open late Wed–Sat, so it works for an evening dessert date","price":"฿฿","hours":"10am–10pm (to midnight Wed–Sat)","date_friendly":true,"night":true,"tags":["floral","instagrammable","afternoon-tea"],"sources":["https://www.thatbangkoklife.com/unique-cafes-in-bangkok/"],"coord_confidence":"medium"},{"id":38,"name":"Wattana Panich","g":"food","category":"restaurant","area":"Ekkamai","lat":13.737,"lng":100.5893,"vibe":"Beef noodle soup from a giant pot that has simmered non-stop for 50+ years","tip":"Beef or goat noodle soup. Look at the cauldron out front. Go at lunch","price":"฿","hours":"~9am–8pm","date_friendly":false,"night":false,"tags":["legendary","viral","michelin-bib"],"sources":["https://www.tastingtable.com/1802014/thai-beef-noodle-soup-simmering-over-50-years","https://www.theworldofstreetfood.com/2025/12/wattana-panich-legendary-50-year-old.html"],"coord_confidence":"medium"},{"id":39,"name":"Tuba Design Furniture & Restaurant","g":"food","category":"restaurant","area":"Ekkamai","lat":13.7405,"lng":100.5895,"vibe":"Eat and drink inside a cluttered vintage furniture warehouse where almost everything is for sale","tip":"Try the tom yum pizza and cocktails. A quirky low-key dinner date","price":"฿฿","hours":"11am–2am","date_friendly":true,"night":true,"tags":["quirky","vintage","bar"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/"],"coord_confidence":"medium"},{"id":40,"name":"Piccolo Vicolo at Wang Burapha","g":"cafe","category":"cafe","area":"Old Town (Wang Burapha canal)","lat":13.747,"lng":100.5005,"vibe":"Restored canal-side shophouses turned into a café with a rooftop, opened 2025","tip":"Matcha coconut on the rooftop. Closed Tuesdays","price":"฿","hours":"Wed–Mon 9am–6pm","date_friendly":true,"night":false,"tags":["new","heritage","rooftop"],"sources":["https://www.timeout.com/bangkok/restaurants/bangkoks-best-new-cafes-of-2025"],"coord_confidence":"low"},{"id":41,"name":"Chocolate Ville","g":"food","category":"restaurant","area":"Kaset-Nawamin (NE Bangkok)","lat":13.8357,"lng":100.6835,"vibe":"Fake European village with a lighthouse, lake and fairy lights: peak cheesy-romantic","tip":"Arrive before sunset and stay for the lights. The setting matters more than the food. A taxi ride out","price":"฿฿","hours":"~4pm–midnight","date_friendly":true,"night":true,"tags":["themed","kitsch","romantic","instagrammable"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/","https://thesmartlocal.com/read/chocolate-ville/"],"coord_confidence":"medium"},{"id":42,"name":"747 Café","g":"cafe","category":"cafe","area":"Lat Krabang","lat":13.7385,"lng":100.782,"vibe":"Café inside a decommissioned Boeing 747 where you can sit in the cockpit","tip":"Your entry 'boarding pass' includes drink credit. Pair it with an airport-side trip","price":"฿฿","hours":"9am–6pm","date_friendly":true,"night":false,"tags":["unique","plane","quirky"],"sources":["https://www.myglobalviewpoint.com/unique-restaurants-in-bangkok/","https://thesmartlocal.com/thailand/747-cafe"],"coord_confidence":"low"},{"id":43,"name":"Mustache Bangkok","g":"club","category":"club","area":"Silom (Decho Rd)","lat":13.7262,"lng":100.5262,"vibe":"Bangkok's best-known underground house/tech-house room: VOID Acoustics, a no-phones dancefloor, no song requests","tip":"Fri–Sat 22:00–03:30. ~350฿ presale / 500฿ door incl. a drink. Bring your physical passport, closed shoes","price":"฿฿","hours":"Fri–Sat 22:00–03:30","date_friendly":true,"night":true,"tags":["house-music","tech-house","techno","underground","late-night"],"sources":["https://www.technoairlines.com/club/mustache-bar-bangkok","https://yourthaiguide.com/mustache-bangkok-tourist-faq/","https://bangkok-nights.com/guides/best-techno-clubs-bangkok-2026"],"coord_confidence":"medium"},{"id":44,"name":"Subwerk","g":"club","category":"club","area":"Silom (Decho Rd)","lat":13.7263,"lng":100.5261,"vibe":"Hard and industrial techno in the same building as Mustache, so you can hop between the two rooms","tip":"Fri–Sat only, 22:00–03:00. 300–500฿ incl. a drink. Check IG for psytrance/DnB Saturdays","price":"฿฿","hours":"Fri–Sat 22:00–03:00","date_friendly":false,"night":true,"tags":["techno","hard-techno","underground","late-night"],"sources":["https://bangkok-nights.com/guides/best-techno-clubs-bangkok-2026","https://www.trvlogue.com/en/bangkok-techno-clubs"],"coord_confidence":"medium"},{"id":45,"name":"Elsewhere","g":"club","category":"club","area":"Silom / Chong Nonsi (Trinity Complex)","lat":13.7226,"lng":100.5309,"vibe":"100-cap after-hours room running midnight to dawn: minimal and deep house in the Perlon/Giegling style for heads","tip":"Fri–Sat from midnight. Go after your main night out. Check RA for lineups, 400–600฿","price":"฿฿","hours":"Fri–Sat 00:00–dawn","date_friendly":false,"night":true,"tags":["after-hours","house-music","minimal","underground","secret"],"sources":["https://www.technoairlines.com/club/elsewhere-bangkok","https://bangkok-nights.com/guides/best-techno-clubs-bangkok-2026"],"coord_confidence":"medium"},{"id":46,"name":"DUAL (Sacristy)","g":"club","category":"club","area":"Silom / Chong Nonsi (Trinity Complex)","lat":13.7224,"lng":100.5312,"vibe":"Newest underground club: an 800 m² basement with 2 floors and Funktion-One. Time Out says it's packed most nights","tip":"Fri–Sat from 21:00. Tickets 300–600฿ on Ticketmelon. Entrance is in Trinity Complex, Naradhiwas Soi 3","price":"฿฿","hours":"Fri–Sat 21:00–04:00","date_friendly":false,"night":true,"tags":["techno","house-music","underground","funktion-one","basement"],"sources":["https://www.timeout.com/bangkok/things-to-do/slip-into-dual-bangkoks-newest-underground-club-where-southeast-asian-selectors-take-over","https://www.timeout.com/bangkok/things-to-do/descend-into-duals-basement-for-moscow-techno-and-heavy-bass","https://www.timeout.com/bangkok/news/bangkok-is-officially-the-worlds-best-city-for-nightlife-in-2026-082626"],"coord_confidence":"medium"},{"id":47,"name":"Bar Temp.","g":"club","category":"club","area":"Chinatown / Pom Prap","lat":13.7406,"lng":100.5128,"vibe":"Single room behind a steel door from the More Rice and Never Normal crew: house, techno and deep house on Martin Audio","tip":"Wed–Sun from 19:00, until 3am Fri–Sat. Free on regular nights, 300–700฿ for events. It's about the music, not tables","price":"฿","hours":"Wed–Sun 19:00–01:00 (Fri–Sat to 03:00)","date_friendly":true,"night":true,"tags":["house-music","deep-house","techno","underground","hidden"],"sources":["https://djmag.com/news/bangkok-has-new-underground-focused-club-space-bar-temp","https://www.timeout.com/bangkok/bars/bar-temp","https://www.timeout.com/news/i-live-in-the-worlds-best-city-for-nightlife-here-are-the-8-spots-id-never-gatekeep-090226"],"coord_confidence":"medium"},{"id":48,"name":"Culture Cafe","g":"club","category":"club","area":"Old Town (Samsen Rd)","lat":13.7664,"lng":100.4989,"vibe":"Vinyl-only bar where minimal, dark techno and deep house play to an Old Town crowd","tip":"No cover, you just pay for drinks. Open nightly until 3am. Easy follow-up after Khao San or Banglamphu","price":"฿","hours":"Daily 20:00–03:00","date_friendly":true,"night":true,"tags":["deep-house","vinyl","techno","no-cover","local"],"sources":["https://www.trvlogue.com/en/bangkok-techno-clubs","https://bangkok-nights.com/guides/best-techno-clubs-bangkok-2026"],"coord_confidence":"medium"},{"id":49,"name":"12x12","g":"bar","category":"bar","area":"Ekkamai","lat":13.7318,"lng":100.589,"vibe":"Vintage living-room bar with couches, homemade plum wine and an eclectic house/disco/techno soundtrack","tip":"Tue–Sat from 17:00 or 20:00. Mostly free entry, some events up to 400฿. Good low-key date bar that turns into a dance spot","price":"฿","hours":"Tue–Sat ~17:00–01:30","date_friendly":true,"night":true,"tags":["house-music","disco","vinyl","dive","underground"],"sources":["https://mixmag.asia/read/mixmag-asia-guide-to-the-best-underground-music-clubs-in-bangkok-city-guides","https://www.trvlogue.com/en/bangkok-techno-clubs"],"coord_confidence":"low"},{"id":50,"name":"ETA","g":"club","category":"club","area":"Phrom Phong (Sukhumvit 26)","lat":13.7253,"lng":100.5689,"vibe":"Small, sweaty Sukhumvit room for acid, hard techno, UKG and DnB","tip":"Wed–Sun from 20:00. Arrive before 22:00 to skip the cover (150–500฿ otherwise)","price":"฿","hours":"Wed–Sun 20:00–03:00","date_friendly":false,"night":true,"tags":["techno","acid","ukg","underground"],"sources":["https://www.trvlogue.com/en/bangkok-techno-clubs","https://bangkok-nights.com/guides/best-techno-clubs-bangkok-2026"],"coord_confidence":"medium"},{"id":51,"name":"HORN","g":"club","category":"club","area":"Silom Soi 4","lat":13.7297,"lng":100.5339,"vibe":"Berlin-style bunker on the 4th floor of the Silom 4 gay strip: techno and industrial with a queer, alternative crowd","tip":"Thu–Sat 22:00–03:00, 400–900฿. Themed and fetish nights get announced last-minute on IG, so check first","price":"฿฿","hours":"Thu–Sat 22:00–03:00","date_friendly":false,"night":true,"tags":["techno","queer","underground","berlin-style"],"sources":["https://www.timeout.com/bangkok/bars/horn","https://www.timeout.com/news/i-live-in-the-worlds-best-city-for-nightlife-here-are-the-8-spots-id-never-gatekeep-090226"],"coord_confidence":"medium"},{"id":52,"name":"Clutch Bar (The Warehouse)","g":"bar","category":"bar","area":"Talat Noi / Charoen Krung","lat":13.7346,"lng":100.5129,"vibe":"Raw concrete bar in a building left empty for 30 years. Vinyl and deep house, and it can turn into a full rave","tip":"Climb the stairs past the vintage and tattoo shops. Free most nights, ~300฿ on event nights. Tue–Sun","price":"฿","hours":"Tue–Sun 18:00–late","date_friendly":true,"night":true,"tags":["deep-house","vinyl","warehouse","creative-space"],"sources":["https://www.timeout.com/bangkok/bars/clutch-bar","https://www.timeout.com/news/i-live-in-the-worlds-best-city-for-nightlife-here-are-the-8-spots-id-never-gatekeep-090226"],"coord_confidence":"medium"},{"id":53,"name":"Tropic City","g":"bar","category":"bar","area":"Charoen Krung Soi 28","lat":13.731,"lng":100.5144,"vibe":"Neon tiki cocktail bar where local selectors play house, boogie and breaks on Thu and Fri","tip":"Tue–Sun 19:00–02:00. Go Thu/Fri for DJs. Pair it with the Talat Noi bars nearby","price":"฿฿","hours":"Tue–Sun 19:00–02:00","date_friendly":true,"night":true,"tags":["cocktails","house-music","dj","tiki"],"sources":["https://mixmag.asia/read/mixmag-asia-guide-to-the-best-underground-music-clubs-in-bangkok-city-guides","https://www.timeout.com/bangkok/bars/tropic-city"],"coord_confidence":"medium"},{"id":54,"name":"Sing Sing Theater","g":"club","category":"club","area":"Sukhumvit Soi 45","lat":13.7322,"lng":100.5733,"vibe":"Red-lantern 1930s Shanghai fantasy club by Ashley Sutton (seen in White Lotus S3), with melodic and deep house guests","tip":"Tue–Sat from 21:00. Guest nights ~300฿ incl. a drink (recent guests: Chus & Ceballos). Dress up","price":"฿฿฿","hours":"Tue–Sat 21:00–late","date_friendly":true,"night":true,"tags":["house-music","themed","design","instagrammable"],"sources":["https://www.technoairlines.com/club/sing-sing-theater-bangkok","https://www.timeout.com/bangkok/news/bangkok-is-officially-the-worlds-best-city-for-nightlife-in-2026-082626"],"coord_confidence":"medium"},{"id":55,"name":"Siwilai Radical Club","g":"club","category":"club","area":"Ploenchit (Central Embassy)","lat":13.744,"lng":100.5466,"vibe":"Stylish terrace club atop Central Embassy for disco and house, with dinner-to-dance energy","tip":"Wed–Sat. Smart-casual. Have dinner at Central Embassy first","price":"฿฿฿","hours":"Wed–Sat evening–late","date_friendly":true,"night":true,"tags":["house-music","disco","terrace","stylish"],"sources":["https://mustachebangkok.com/best-underground-clubs-bangkok-2026/","https://design-anthology.com/story/siwilai-radical-club-bangkok"],"coord_confidence":"medium"},{"id":56,"name":"VOID Club","g":"club","category":"club","area":"RCA / Rama 9","lat":13.7508,"lng":100.5745,"vibe":"RCA's big-room club for progressive house, trance and psy, plus occasional techno takeovers","tip":"Nightly 21:30–03:30, ~500฿. Age 20+, ID checked. Go for themed Halloween or progressive nights","price":"฿฿","hours":"Daily 21:30–03:30","date_friendly":false,"night":true,"tags":["club","progressive-house","rca","big-room"],"sources":["https://www.technoairlines.com/club/void-bangkok"],"coord_confidence":"low"},{"id":57,"name":"Tichuca Rooftop","g":"rooftop","category":"rooftop","area":"Thonglor / Ekkamai (T-One, Sukhumvit 40)","lat":13.7202,"lng":100.582,"vibe":"Jungle rooftop on floors 46–50 with a glowing LED tree, tiki drinks and tropical house DJs over the skyline","tip":"Queues are long, so go at opening or book. Better with a group. Smart-casual","price":"฿฿฿","hours":"Daily ~17:00–01:00","date_friendly":true,"night":true,"tags":["rooftop","view","dj","tropical-house","instagrammable"],"sources":["https://www.timeout.com/bangkok/clubs/best-clubs-where-people-go-to-dance","https://www.timeout.com/news/i-live-in-the-worlds-best-city-for-nightlife-here-are-the-8-spots-id-never-gatekeep-090226"],"coord_confidence":"medium"},{"id":58,"name":"Octave Rooftop Lounge","g":"rooftop","category":"rooftop","area":"Thonglor (Marriott Sukhumvit)","lat":13.7233,"lng":100.5794,"vibe":"Three open-air levels with 360° views, and DJs most nights on the top deck","tip":"Arrive around 17:30 for sunset happy hour. Smart-casual. Right next to BTS Thong Lo","price":"฿฿฿","hours":"Daily 17:00–02:00","date_friendly":true,"night":true,"tags":["rooftop","view","dj","sunset"],"sources":["https://www.bkmagazine.com/nightlife/bars/nightlife-article-bangkoks-best-rooftop-bars/","https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"high"},{"id":59,"name":"ÆTHER","g":"rooftop","category":"rooftop","area":"Silom / Saladaeng (Dusit Central Park)","lat":13.729,"lng":100.5367,"vibe":"New 44th-floor 360° cocktail bar with a giant silver speaker framing the skyline, one of 2026's hottest openings","tip":"Arrive around 17:45 to catch sunset and the shift into night. Book on weekends","price":"฿฿฿฿","hours":"Daily from ~17:00","date_friendly":true,"night":true,"tags":["rooftop","view","new-2026","cocktails","sunset"],"sources":["https://www.timeout.com/bangkok/bars/bangkoks-best-new-bars-in-2026","https://www.timeout.com/bangkok/news/bangkok-is-officially-the-worlds-best-city-for-nightlife-in-2026-082626"],"coord_confidence":"high"},{"id":60,"name":"The NORM Bangkok","g":"rooftop","category":"rooftop","area":"Silom / Saladaeng (Dusit Central Park)","lat":13.7292,"lng":100.5369,"vibe":"42nd-floor design social club full of Fritz Hansen furniture, with a sunset DJ on the terrace and a private Whispering Room","tip":"Book ahead on Fri/Sat and ask for the terrace. You can combine it with ÆTHER two floors up","price":"฿฿฿฿","hours":"Daily evening–late","date_friendly":true,"night":true,"tags":["rooftop","dj","terrace","design","new-2026"],"sources":["https://www.timeout.com/bangkok/bars/bangkoks-best-new-bars-in-2026"],"coord_confidence":"high"},{"id":61,"name":"Wild Iris (SO/ Bangkok)","g":"rooftop","category":"rooftop","area":"Lumpini / Rama IV","lat":13.7262,"lng":100.5443,"vibe":"French Riviera–style 29th-floor bar above Lumpini Park: a DJ-led main floor plus a quiet garden terrace upstairs","tip":"Go at sunset. Head upstairs to talk and stay downstairs for the DJ. Signatures ~450฿","price":"฿฿฿","hours":"Daily from ~17:00","date_friendly":true,"night":true,"tags":["rooftop","dj","view","terrace","new-2026"],"sources":["https://www.timeout.com/bangkok/bars/bangkoks-best-new-bars-in-2026"],"coord_confidence":"high"},{"id":62,"name":"Sky Beach (King Power Mahanakhon)","g":"rooftop","category":"rooftop","area":"Silom / Chong Nonsi","lat":13.7236,"lng":100.5282,"vibe":"Bangkok's highest open-air bar on the 78th floor: beanbags, a 360° panorama, and the glass Skywalk next door","tip":"Book the Skywalk + bar combo ticket, go at sunset, and dress smart","price":"฿฿฿฿","hours":"Daily ~17:00–00:00","date_friendly":true,"night":true,"tags":["rooftop","view","iconic","sunset"],"sources":["https://www.bkmagazine.com/nightlife/bars/nightlife-article-bangkoks-best-rooftop-bars/"],"coord_confidence":"high"},{"id":63,"name":"Sky Bar (Lebua State Tower)","g":"rooftop","category":"rooftop","area":"Silom / Riverside","lat":13.7216,"lng":100.5167,"vibe":"The Hangover II rooftop: a glowing golden dome 63 floors above the Chao Phraya","tip":"Dress code is strict (no shorts or sandals). Have one drink at sunset and move on, it's pricey","price":"฿฿฿฿","hours":"Daily 18:00–00:00","date_friendly":true,"night":true,"tags":["rooftop","view","iconic","river"],"sources":["https://tablejourney.com/thailand/bangkok/nightlife/","https://www.phuket101.net/bangkok/best-rooftop-bars-in-bangkok/"],"coord_confidence":"high"},{"id":64,"name":"Vertigo & Moon Bar","g":"rooftop","category":"rooftop","area":"Sathorn (Banyan Tree)","lat":13.7239,"lng":100.5398,"vibe":"Open-air ledge on the 61st floor with no glass walls, just a 360° city view","tip":"Closes in rain. Smart dress. Book a sunset slot","price":"฿฿฿฿","hours":"Daily ~17:00–01:00","date_friendly":true,"night":true,"tags":["rooftop","view","iconic"],"sources":["https://www.bkmagazine.com/nightlife/bars/nightlife-article-bangkoks-best-rooftop-bars/","https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"high"},{"id":65,"name":"The Speakeasy (Hotel Muse)","g":"rooftop","category":"rooftop","area":"Langsuan","lat":13.7392,"lng":100.5436,"vibe":"1920s Art Deco rooftop speakeasy with a retractable roof and DJs Thu–Sat","tip":"Find the panel with the life-size painting of a 1920s couple. DJs from 20:30 Thu–Sat","price":"฿฿฿","hours":"Daily ~17:00–01:00","date_friendly":true,"night":true,"tags":["rooftop","speakeasy","dj","art-deco","hidden"],"sources":["https://www.bkmagazine.com/nightlife/bars/nightlife-article-bangkoks-best-rooftop-bars/","https://www.masalathai.com/trending/our-guide-to-bangkoks-hidden-juice-joints"],"coord_confidence":"medium"},{"id":66,"name":"Bar.Yard (Kimpton Maa-Lai)","g":"rooftop","category":"rooftop","area":"Langsuan / Soi Ton Son","lat":13.74,"lng":100.5452,"vibe":"Leafy 40th-floor backyard-style rooftop with weekly themed party nights and dance-offs","tip":"Check IG for party nights. Casual-smart. Easy after dinner in Langsuan","price":"฿฿฿","hours":"Daily ~17:00–00:00","date_friendly":true,"night":true,"tags":["rooftop","party","dj","terrace"],"sources":["https://www.bkmagazine.com/nightlife/bars/nightlife-article-bangkoks-best-rooftop-bars/"],"coord_confidence":"medium"},{"id":67,"name":"SIN Rooftop (Avani+ Riverside)","g":"rooftop","category":"rooftop","area":"Riverside / Thonburi","lat":13.7078,"lng":100.4985,"vibe":"Club-style 26th-floor rooftop with a big DJ booth and wide Chao Phraya river views","tip":"Weekend nights for DJs. Take the hotel shuttle boat from Sathorn Pier","price":"฿฿฿","hours":"Daily evening–late","date_friendly":true,"night":true,"tags":["rooftop","dj","river","view"],"sources":["https://www.bkmagazine.com/nightlife/bars/nightlife-article-bangkoks-best-rooftop-bars/"],"coord_confidence":"low"},{"id":68,"name":"ThreeSixty Lounge (Millennium Hilton)","g":"live","category":"live-music","area":"Riverside / Thonburi","lat":13.7268,"lng":100.5108,"vibe":"Glass-dome jazz lounge high above the river, with live singers and the city lights below","tip":"Get a window seat. Live jazz from ~20:00. Cross by the hotel boat from Sathorn Pier","price":"฿฿฿","hours":"Daily ~17:00–01:00","date_friendly":true,"night":true,"tags":["jazz","view","river","rooftop"],"sources":["https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"medium"},{"id":69,"name":"Bar Us","g":"bar","category":"bar","area":"Phrom Phong (Sukhumvit 26)","lat":13.7241,"lng":100.5686,"vibe":"Pitch-black 14-seat 'drinking room' (#6 Asia's 50 Best 2026) with savoury cocktails served like courses","tip":"Book via us-bar.com and sit at the counter. Try the Super Banana Daiquiri. Sister bar Lime by Us is next door","price":"฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["asia-50-best","cocktails","intimate"],"sources":["https://www.bkmagazine.com/nightlife/bars/8-bangkok-bars-rank-on-the-asias-50-best-bars-2026/","https://www.timeout.com/bangkok/bars/bar-us"],"coord_confidence":"medium"},{"id":70,"name":"Dry Wave Cocktail Studio","g":"bar","category":"bar","area":"Thonglor (Soi 13)","lat":13.7335,"lng":100.5816,"vibe":"Bangkok's top bar in 2026 (#4 Asia's 50 Best): lab-style 'studio' cocktails from Palm Muttarattana","tip":"Find it on the 2nd floor of the Sodality building, Thonglor 13. Book on weekends","price":"฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["asia-50-best","cocktails","innovative"],"sources":["https://www.bkmagazine.com/nightlife/bars/8-bangkok-bars-rank-on-the-asias-50-best-bars-2026/","https://www.diffordsguide.com/bars/9m2Jo5/dry-wave-cocktail-studio"],"coord_confidence":"medium"},{"id":71,"name":"Lennon's (Rosewood)","g":"bar","category":"bar","area":"Ploenchit","lat":13.7429,"lng":100.5487,"vibe":"Lift-access speakeasy styled as a mid-century recording studio, with 6,000+ vinyl records (#7 Asia's 50 Best 2026)","tip":"Take the Rosewood lift to the 30th floor. Try the mango sticky rice Mando-tini. Pick a record","price":"฿฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["asia-50-best","speakeasy","vinyl","view"],"sources":["https://silverkris.singaporeair.com/experience/food-drink/the-2026-guide-to-bangkoks-best-cocktail-bars/","https://www.bkmagazine.com/nightlife/bars/8-bangkok-bars-rank-on-the-asias-50-best-bars-2026/"],"coord_confidence":"high"},{"id":72,"name":"Bar Sathorn (The House on Sathorn)","g":"bar","category":"bar","area":"Sathorn","lat":13.7214,"lng":100.5288,"vibe":"Cocktails in an 1889 mansion (#17 Asia's 50 Best 2026), with vinyl sets from the resident DJ","tip":"Order the pad-krapow Bloody Mary. Drinks 320–450฿. Next to BTS Chong Nonsi","price":"฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["asia-50-best","heritage","cocktails","vinyl"],"sources":["https://silverkris.singaporeair.com/experience/food-drink/the-2026-guide-to-bangkoks-best-cocktail-bars/","https://www.bkmagazine.com/nightlife/bars/8-bangkok-bars-rank-on-the-asias-50-best-bars-2026/"],"coord_confidence":"high"},{"id":73,"name":"BKK Social Club (Four Seasons)","g":"bar","category":"bar","area":"Riverside / Charoen Krung","lat":13.7143,"lng":100.5131,"vibe":"Glamorous Art Nouveau bar with Buenos Aires flair (#20 Asia's 50 Best 2026), with cigar and champagne courtyards","tip":"Order the Chiapas espresso martini with popcorn. Smart dress. Book","price":"฿฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["asia-50-best","luxury","cocktails","riverside"],"sources":["https://silverkris.singaporeair.com/experience/food-drink/the-2026-guide-to-bangkoks-best-cocktail-bars/","https://www.bkmagazine.com/nightlife/bars/8-bangkok-bars-rank-on-the-asias-50-best-bars-2026/"],"coord_confidence":"medium"},{"id":74,"name":"Opium Bar (Potong)","g":"bar","category":"bar","area":"Chinatown","lat":13.7401,"lng":100.5079,"vibe":"Secret-feeling bar at the top of a 120-year-old shophouse, reached by a tiny lift (#25 Asia's 50 Best)","tip":"Enter through the Potong restaurant and take the little lift up. Book on weekends","price":"฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["asia-50-best","hidden","heritage","chinatown"],"sources":["https://www.bkmagazine.com/nightlife/bars/8-bangkok-bars-rank-on-the-asias-50-best-bars-2026/","https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"medium"},{"id":75,"name":"G.O.D (Genius.On.Drugs)","g":"bar","category":"bar","area":"Chinatown (Soi Nana)","lat":13.7398,"lng":100.5135,"vibe":"Church-like shophouse bar from the Teens of Thailand team (#31 Asia's 50 Best 2026)","tip":"Daily 19:00–01:30. Start a Soi Nana bar crawl here","price":"฿฿","hours":"Daily 19:00–01:30","date_friendly":true,"night":true,"tags":["asia-50-best","chinatown","bar-crawl"],"sources":["https://www.timeout.com/bangkok/bars/g-o-d","https://www.bkmagazine.com/nightlife/bars/8-bangkok-bars-rank-on-the-asias-50-best-bars-2026/"],"coord_confidence":"medium"},{"id":76,"name":"Tep Bar","g":"live","category":"live-music","area":"Chinatown (Soi Nana)","lat":13.7395,"lng":100.5138,"vibe":"Unsigned shophouse bar with ya dong (herbal Thai whisky) shots and a live traditional Thai band","tip":"There's no sign, so follow the music. Band Fri–Sun from 19:00. Arrive early, it fills fast","price":"฿฿","hours":"Daily 18:00–01:00","date_friendly":true,"night":true,"tags":["live-music","thai-spirits","chinatown","hidden"],"sources":["https://www.timeout.com/news/i-live-in-the-worlds-best-city-for-nightlife-here-are-the-8-spots-id-never-gatekeep-090226","https://www.bkmagazine.com/nightlife/absolute-best-bars-charoenkrung-and-chinatown/"],"coord_confidence":"medium"},{"id":77,"name":"Teens of Thailand","g":"bar","category":"bar","area":"Chinatown (Soi Nana)","lat":13.7393,"lng":100.5136,"vibe":"Tiny, dark gin bar behind a heavy wooden door, a pioneer of the Soi Nana scene","tip":"Look for the old wooden door with no sign. Wed–Sun. Neon sister bar Asia Today is across the street","price":"฿฿","hours":"Wed–Sun 18:00–00:30","date_friendly":true,"night":true,"tags":["speakeasy","gin","chinatown","hidden"],"sources":["https://www.bkmagazine.com/nightlife/absolute-best-bars-charoenkrung-and-chinatown/","https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"medium"},{"id":78,"name":"Ba Hao","g":"bar","category":"bar","area":"Chinatown (Soi Nana)","lat":13.7402,"lng":100.5133,"vibe":"Neon Chinese-signage bar open to Yaowarat street life, serving herbal-medicine cocktails like a ginseng Negroni","tip":"Grab a street-facing seat and people-watch. Open daily","price":"฿฿","hours":"Daily 18:00–00:00","date_friendly":true,"night":true,"tags":["chinatown","neon","cocktails","instagrammable"],"sources":["https://www.bkmagazine.com/nightlife/absolute-best-bars-charoenkrung-and-chinatown/","https://www.timeout.com/bangkok/news/bangkok-is-officially-the-worlds-best-city-for-nightlife-in-2026-082626"],"coord_confidence":"medium"},{"id":79,"name":"Wallflowers Upstairs","g":"rooftop","category":"rooftop","area":"Chinatown (Soi Nana)","lat":13.7399,"lng":100.5138,"vibe":"Fairy-lit plant-jungle rooftop up a creaky wooden staircase above a flower café","tip":"Thu–Sun only. Climb past the café. A romantic end to the Soi Nana crawl","price":"฿฿","hours":"Thu–Sun 18:00–00:00","date_friendly":true,"night":true,"tags":["rooftop","garden","romantic","chinatown"],"sources":["https://www.bkmagazine.com/nightlife/bars/nightlife-article-bangkoks-best-rooftop-bars/","https://www.bkmagazine.com/nightlife/guide-to-soi-nana-coolest-nightlife-neighborhood-bangkok/"],"coord_confidence":"medium"},{"id":80,"name":"Tax (Insect Bar)","g":"bar","category":"bar","area":"Chinatown / Pom Prap","lat":13.7408,"lng":100.5131,"vibe":"Cocktails built on edible insects, every drink served with a bug snack. Great date icebreaker","tip":"Start with the Bamboo Worm cocktail. Daily 19:00–00:30. Next to Bar Temp. for afterwards","price":"฿฿","hours":"Daily 19:00–00:30","date_friendly":true,"night":true,"tags":["quirky","insects","cocktails","chinatown"],"sources":["https://www.timeout.com/bangkok/bars/tax","https://silverkris.singaporeair.com/experience/food-drink/the-2026-guide-to-bangkoks-best-cocktail-bars/"],"coord_confidence":"low"},{"id":81,"name":"Messengerservice Bar","g":"bar","category":"bar","area":"Chinatown / Pom Prap","lat":13.7437,"lng":100.5117,"vibe":"'Grocery store' cocktail bar with shelves of ingredient bottles on the 3rd floor of a heritage building (#69 Asia 50 Best)","tip":"It's in the Baan Trok Tua Ngork building, 306 Santiphap Rd. Closed Mon, open late Fri–Sun","price":"฿฿฿","hours":"Tue–Thu 18:00–00:00, Fri–Sun 18:00–late","date_friendly":true,"night":true,"tags":["asia-50-best","heritage","cocktails","hidden"],"sources":["https://www.bkmagazine.com/food/messengerservice-bar-relocates-to-chinatown-sleek-look-and-hot-new-cocktails/","https://www.bkmagazine.com/nightlife/four-bangkok-bars-make-the-asias-50-best-bars-51-100-2026/"],"coord_confidence":"low"},{"id":82,"name":"Mahaniyom Cocktail Bar","g":"bar","category":"bar","area":"Si Phraya / Bang Rak","lat":13.7296,"lng":100.517,"vibe":"Thai-ingredient cocktail bar above the 100 Mahaseth Isaan restaurant (Asia's 50 Best 51–100)","tip":"Eat Isaan downstairs first, then go up. Book on weekends","price":"฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["asia-50-best","thai-ingredients","cocktails"],"sources":["https://www.tatlerasia.com/maps/tatler-best-thailand-the-best-20-bars-of-2026","https://www.bkmagazine.com/nightlife/four-bangkok-bars-make-the-asias-50-best-bars-51-100-2026/"],"coord_confidence":"medium"},{"id":83,"name":"Vesper","g":"bar","category":"bar","area":"Silom (Convent Rd)","lat":13.7259,"lng":100.5347,"vibe":"Polished Italian-leaning cocktail bar and long-time Asia's 50 Best fixture, great for a classy first date","tip":"Order a martini or one of the barrel-aged drinks. Book on Fri/Sat","price":"฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["asia-50-best","cocktails","classy"],"sources":["https://www.bkmagazine.com/nightlife/four-bangkok-bars-make-the-asias-50-best-bars-51-100-2026/","https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"medium"},{"id":84,"name":"F*nkytown","g":"bar","category":"bar","area":"Phrom Phong (Sukhumvit 37)","lat":13.729,"lng":100.5712,"vibe":"Disco-themed party bar with cocktails ranked by 'level of funk', all the way up to a Tom Yum highball","tip":"Start gentle with the Pain au Matcha. Don't skip the smash burger. A short walk from Bar Us","price":"฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["disco","party","cocktails","fun"],"sources":["https://silverkris.singaporeair.com/experience/food-drink/the-2026-guide-to-bangkoks-best-cocktail-bars/","https://www.theinfatuation.com/bangkok/reviews/funkytown"],"coord_confidence":"medium"},{"id":85,"name":"#FindTheLockerRoom","g":"bar","category":"bar","area":"Thonglor","lat":13.731,"lng":100.5801,"vibe":"Speakeasy hidden behind a wall of steel gym lockers, and you have to find the right one","tip":"Go down the unmarked alley at 406 Sukhumvit 55 and slide open the right locker. Daily until 2am","price":"฿฿฿","hours":"Daily 19:00–02:00","date_friendly":true,"night":true,"tags":["speakeasy","secret-door","hidden","cocktails"],"sources":["https://www.timeout.com/bangkok/bars/findthelockerroom","https://www.tatlerasia.com/maps/tatler-best-thailand-the-best-20-bars-of-2026"],"coord_confidence":"medium"},{"id":86,"name":"#FindThePhotoBooth","g":"bar","category":"bar","area":"Banthat Thong","lat":13.7385,"lng":100.5254,"vibe":"Mint-green shophouse where a hidden button on an 'out of service' photo booth opens the bar","tip":"Press the hidden button on the booth. Then go street-food hopping on Banthat Thong","price":"฿฿","hours":"Daily 18:00–01:30","date_friendly":true,"night":true,"tags":["speakeasy","secret-door","hidden","street-food"],"sources":["https://www.timeout.com/bangkok/bars/find-the-photo-booth","https://www.bkmagazine.com/nightlife/find-photobooths-new-cocktail-menu-all-about-bantadthong-food/","https://www.tatlerasia.com/maps/tatler-best-thailand-the-best-20-bars-of-2026"],"coord_confidence":"low"},{"id":87,"name":"Havana Social","g":"club","category":"club","area":"Sukhumvit Soi 11 (Nana)","lat":13.7441,"lng":100.5556,"vibe":"1950s Havana speakeasy behind an old phone booth: Cuban band, then salsa, reggaeton and Latin house","tip":"Dial the code shown by the phone in the booth. A live Cuban band plays on weekends, so go late","price":"฿฿","hours":"Daily ~18:00–02:00","date_friendly":true,"night":true,"tags":["speakeasy","secret-door","latin","dancing"],"sources":["https://www.timeout.com/bangkok/clubs/best-clubs-where-people-go-to-dance","https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"medium"},{"id":88,"name":"Rabbit Hole","g":"bar","category":"bar","area":"Thonglor","lat":13.7293,"lng":100.5796,"vibe":"Craft-cocktail house behind an unmarked wooden-slat door on Thonglor, with house-leaning DJ nights","tip":"There's no sign: look for the slatted wooden facade. Weekends have DJs upstairs","price":"฿฿฿","hours":"Daily 19:00–02:00","date_friendly":true,"night":true,"tags":["speakeasy","hidden","cocktails","dj"],"sources":["https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"medium"},{"id":89,"name":"The Bamboo Bar (Mandarin Oriental)","g":"live","category":"live-music","area":"Riverside / Charoen Krung","lat":13.7237,"lng":100.5145,"vibe":"Legendary 1953 jazz room with tiger-print booths and live bands six nights a week","tip":"Book for the 21:00 set. Smart dress. Pair it with a riverside walk","price":"฿฿฿฿","hours":"Daily 17:00–01:00","date_friendly":true,"night":true,"tags":["jazz","live-music","classic","riverside"],"sources":["https://citynomads.com/best-jazz-bars-clubs-in-bangkok-thailand/","https://www.tatlerasia.com/maps/tatler-best-thailand-the-best-20-bars-of-2026"],"coord_confidence":"high"},{"id":90,"name":"Saxophone Pub","g":"live","category":"live-music","area":"Victory Monument","lat":13.7637,"lng":100.538,"vibe":"Old-school jazz, blues and reggae pub since 1987, full of locals and Singha","tip":"Bands play nightly, so go after 21:00. Cheap and casual, no dress code. BTS Victory Monument","price":"฿","hours":"Daily 18:00–02:00","date_friendly":true,"night":true,"tags":["jazz","blues","live-music","local"],"sources":["https://citynomads.com/best-jazz-bars-clubs-in-bangkok-thailand/","https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"medium"},{"id":91,"name":"Brown Sugar","g":"live","category":"live-music","area":"Old Town (Phra Sumen Rd)","lat":13.7627,"lng":100.4987,"vibe":"Bangkok's oldest jazz and blues club (since 1985), in a cosy Banglamphu shophouse","tip":"Live music from 21:00. Combine with Adhere the 13th nearby for a blues crawl","price":"฿฿","hours":"Daily 17:00–01:00 (Fri–Sat to 02:00)","date_friendly":true,"night":true,"tags":["jazz","blues","live-music","old-town"],"sources":["https://citynomads.com/best-jazz-bars-clubs-in-bangkok-thailand/"],"coord_confidence":"medium"},{"id":92,"name":"Adhere the 13th Blues Bar","g":"live","category":"live-music","area":"Old Town (Samsen Rd)","lat":13.7641,"lng":100.4981,"vibe":"Shoebox blues bar where the band is practically in your lap, a Banglamphu institution","tip":"Arrive by 21:30 for a seat. Cash only. 10 minutes' walk from Khao San","price":"฿","hours":"Daily ~18:00–00:00","date_friendly":true,"night":true,"tags":["blues","live-music","dive","old-town"],"sources":["https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"medium"},{"id":93,"name":"Wong's Place","g":"bar","category":"bar","area":"Sathorn (Soi Sri Bamphen)","lat":13.7214,"lng":100.5441,"vibe":"Wood-panelled cult dive running since 1987 that keeps pouring long after everything else shuts","tip":"Go very late (after 1am). Cash, cheap beer, self-serve fridge vibes","price":"฿","hours":"Late night–dawn","date_friendly":false,"night":true,"tags":["dive","late-night","cult","after-hours"],"sources":["https://tablejourney.com/thailand/bangkok/nightlife/late-night-dives/","https://www.afar.com/places/wongs-place-bangkok"],"coord_confidence":"medium"},{"id":94,"name":"Sala Saneha","g":"bar","category":"bar","area":"Silom (Soi Decho)","lat":13.7255,"lng":100.5263,"vibe":"Wine bar, bookshop and a 25-seat armchair cinema in a 70-year-old building. You can bring your glass into the film","tip":"Thu–Mon 18:00–00:00. Book a screening, then walk to Mustache on the same road","price":"฿฿฿","hours":"Thu–Mon 18:00–00:00","date_friendly":true,"night":true,"tags":["quirky","cinema","wine","date-night","new-2026"],"sources":["https://www.timeout.com/bangkok/bars/bangkoks-best-new-bars-in-2026","https://www.timeout.com/news/i-live-in-the-worlds-best-city-for-nightlife-here-are-the-8-spots-id-never-gatekeep-090226"],"coord_confidence":"medium"},{"id":95,"name":"FooJohn Building","g":"bar","category":"bar","area":"Talat Noi / Charoen Krung","lat":13.7326,"lng":100.5139,"vibe":"Restored 1960s shophouse with a bistro downstairs, a hidden cocktail bar upstairs and a rooftop BBQ","tip":"Ask for the upstairs bar, then finish on the roof. 831 Charoen Krung Soi 31","price":"฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["hidden","rooftop","heritage","talat-noi"],"sources":["https://tablejourney.com/thailand/bangkok/nightlife/late-night-dives/"],"coord_confidence":"medium"},{"id":96,"name":"Iron Balls Distillery","g":"bar","category":"bar","area":"Ekkamai (Park Lane)","lat":13.7243,"lng":100.5862,"vibe":"Steampunk gin distillery bar with the copper still right behind the counter","tip":"Order the house coconut-gin G&T. The basement is booths only, good for a date","price":"฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["themed","steampunk","gin","quirky"],"sources":["https://tablejourney.com/thailand/bangkok/nightlife/late-night-dives/"],"coord_confidence":"medium"},{"id":97,"name":"Firefly Bar (Sindhorn Kempinski)","g":"live","category":"live-music","area":"Langsuan / Lumpini","lat":13.7366,"lng":100.5447,"vibe":"Sultry jazz lounge with 370+ spirits (Asia's 50 Best 51–100) and a cricket-protein cocktail","tip":"Order 'Where Is The Cricket?' if you dare. Cocktails 490–650฿. Smart dress","price":"฿฿฿฿","hours":"Evenings–late","date_friendly":true,"night":true,"tags":["jazz","asia-50-best","luxury","cocktails"],"sources":["https://silverkris.singaporeair.com/experience/food-drink/the-2026-guide-to-bangkoks-best-cocktail-bars/","https://www.bkmagazine.com/nightlife/four-bangkok-bars-make-the-asias-50-best-bars-51-100-2026/"],"coord_confidence":"medium"},{"id":98,"name":"Khaoya Archive","g":"bar","category":"bar","area":"Ari","lat":13.779,"lng":100.5442,"vibe":"New Ari cocktail den built on Thai local ingredients, with an ever-changing menu","tip":"Wed–Sun 19:00–01:00, upstairs at No Bar Wine Bar. Try the mango-passionfruit gin fizz (420฿)","price":"฿฿","hours":"Wed–Sun 19:00–01:00","date_friendly":true,"night":true,"tags":["cocktails","thai-ingredients","ari","new-2026"],"sources":["https://www.timeout.com/bangkok/bars/bangkoks-best-new-bars-in-2026"],"coord_confidence":"low"},{"id":99,"name":"Maggie Choo's","g":"live","category":"live-music","area":"Silom","lat":13.7252,"lng":100.5238,"vibe":"1930s Shanghai basement speakeasy (a former bank vault), with jazz bands and silk-clad performers on swings","tip":"Go down the stairs under Novotel Fenix Silom. Jazz from ~21:30. Status not confirmed for 2026, so check IG first","price":"฿฿","hours":"Daily 19:30–02:00","date_friendly":true,"night":true,"tags":["speakeasy","themed","jazz","basement"],"sources":["https://citynomads.com/best-jazz-bars-clubs-in-bangkok-thailand/","https://tablejourney.com/thailand/bangkok/nightlife/"],"coord_confidence":"low"},{"id":100,"name":"Siriraj Medical Museum (\"Museum of Death\")","g":"museum","category":"museum","area":"Bangkok Noi (Thonburi)","lat":13.7586,"lng":100.4857,"vibe":"Forensic and pathology museum full of jarred specimens, crime-scene relics and conjoined twins. Bangkok's most famous weird museum","tip":"Closed Tue. ฿200 for foreigners. Allow 1.5-2h. Take the ferry to Wang Lang pier. Not for the squeamish","price":"฿","hours":"Wed-Mon 10:00-17:00","date_friendly":true,"night":false,"tags":["weird","medical","forensic","dark"],"sources":["https://www.timeout.com/bangkok/museums/bangkoks-strangest-museums-and-attractions","https://www.atlasobscura.com/things-to-do/bangkok-thailand","https://rajadamnern.com/blog/crazy-things-to-do-in-bangkok/"],"coord_confidence":"medium"},{"id":101,"name":"Human Body Museum, Chulalongkorn University","g":"museum","category":"museum","area":"Pathum Wan (Chula)","lat":13.7405,"lng":100.531,"vibe":"Free teaching collection of about 2,000 real specimens, including full nervous-system dissections","tip":"9th floor of the Dentistry building. Open Mon and Fri all day, Wed mornings. Shoes off, no photos","price":"free","hours":"Mon & Fri 9:00-16:00, Wed 9:00-12:00","date_friendly":false,"night":false,"tags":["weird","medical","free","hidden"],"sources":["https://www.timeout.com/bangkok/museums/bangkoks-strangest-museums-and-attractions"],"coord_confidence":"medium"},{"id":102,"name":"Condom Museum (Dept. of Medical Sciences)","g":"museum","category":"museum","area":"Nonthaburi (Tiwanon)","lat":13.85,"lng":100.5265,"vibe":"An unsigned government museum about condom testing and HIV campaigns, as odd as it sounds","tip":"Weekdays only, until 14:30. Door often locked, so ask the staff by the lift. Purple Line to Ministry of Public Health","price":"free","hours":"Mon-Fri 8:30-14:30","date_friendly":true,"night":false,"tags":["weird","quirky","free","hidden"],"sources":["https://www.timeout.com/bangkok/museums/bangkoks-strangest-museums-and-attractions"],"coord_confidence":"low"},{"id":103,"name":"Snake Farm - Queen Saovabha Memorial Institute","g":"show","category":"show","area":"Pathum Wan (Rama IV / Henri Dunant)","lat":13.7325,"lng":100.5363,"vibe":"Red Cross antivenom lab where staff milk king cobras and drape pythons on visitors","tip":"Venom extraction show weekdays 11:00. Handling show weekdays 14:30, weekends 11:00. Takes about 1h","price":"฿","hours":"Daily, daytime","date_friendly":true,"night":false,"tags":["animals","show","weird","snakes"],"sources":["https://www.timeout.com/bangkok/museums/bangkoks-strangest-museums-and-attractions","https://rajadamnern.com/blog/crazy-things-to-do-in-bangkok/"],"coord_confidence":"medium"},{"id":104,"name":"Chao Mae Tubtim Shrine (phallus shrine)","g":"sight","category":"landmark","area":"Ploenchit / Nai Lert Park","lat":13.746,"lng":100.547,"vibe":"Canal-side fertility shrine surrounded by hundreds of carved wooden phalluses","tip":"Beside Nai Lert Park Heritage Home. An active place of worship, so dress modestly. 15 minutes is enough","price":"free","hours":"Daytime","date_friendly":true,"night":false,"tags":["weird","shrine","quirky","hidden"],"sources":["https://www.timeout.com/bangkok/museums/bangkoks-strangest-museums-and-attractions"],"coord_confidence":"medium"},{"id":105,"name":"Nai Lert Park Heritage Home","g":"museum","category":"museum","area":"Ploenchit","lat":13.7458,"lng":100.5476,"vibe":"Restored 1915 teak mansion and garden hidden among the skyscrapers. Quiet old-Bangkok charm","tip":"Wed-Sun only. Guided tours at 9:30, 11:30, 14:30 and 16:30. About ฿250-350","price":"฿฿","hours":"Wed-Sun 9:30-16:30","date_friendly":true,"night":false,"tags":["heritage","garden","hidden"],"sources":["https://www.timeout.com/bangkok/museums/bangkoks-strangest-museums-and-attractions"],"coord_confidence":"medium"},{"id":106,"name":"BatCat Museum & Toys","g":"museum","category":"museum","area":"Hua Mak / Bang Kapi","lat":13.7488,"lng":100.6229,"vibe":"More than 50,000 toys, said to be Asia's largest Batman collection, plus Marvel, Star Wars and life-size figures","tip":"Closed Mon. ฿250 for foreigners. Take the Khlong Saen Saep boat to The Mall Bangkapi pier. Allow 1-1.5h","price":"฿","hours":"Tue-Sun 9:00-17:00","date_friendly":true,"night":false,"tags":["quirky","pop-culture","nerdy","photo"],"sources":["https://www.timeout.com/bangkok/museums/bangkoks-strangest-museums-and-attractions","https://www.timeout.com/bangkok/museums/batcat-museum-toys"],"coord_confidence":"low"},{"id":107,"name":"Siam Serpentarium","g":"museum","category":"museum","area":"Lat Krabang","lat":13.7275,"lng":100.748,"vibe":"Immersive snake museum with 70+ live species in habitat-style enclosures and a giant snake sculpture","tip":"Airport Rail Link to Lat Krabang, Exit 2. About ฿350. Good to combine with a trip to or from the airport","price":"฿฿","hours":"Mon-Fri 10:00-17:00, Sat-Sun 10:00-18:00","date_friendly":true,"night":false,"tags":["animals","immersive","snakes"],"sources":["https://www.timeout.com/bangkok/museums/bangkoks-strangest-museums-and-attractions"],"coord_confidence":"low"},{"id":108,"name":"Art in Paradise (3D trick-eye museum)","g":"museum","category":"museum","area":"Ratchada (Esplanade)","lat":13.766,"lng":100.5694,"vibe":"Illusion art you climb into. Silly photos of you being eaten by sharks or hanging off cliffs","tip":"4th floor of Esplanade Ratchada, MRT Thailand Cultural Centre. Allow 1.5h. Charge your phone first","price":"฿฿","hours":"Daily ~10:00-21:00","date_friendly":true,"night":false,"tags":["illusion","trick-eye","photo","silly"],"sources":["https://rajadamnern.com/blog/crazy-things-to-do-in-bangkok/","https://www.bangkokbeyond.com/blog/?p=9310"],"coord_confidence":"medium"},{"id":109,"name":"Cave Fantasy (immersive light park)","g":"museum","category":"art","area":"Siam (MBK Center)","lat":13.7446,"lng":100.53,"vibe":"New 2026 glasses-free 3D rooms (cosmic jellyfish, glowing forest) plus a 4D flight theatre with wind and snow","tip":"MBK Zone A, 4th floor. ฿499, re-entry allowed. Takes 1-2h. Open until 21:00-21:30","price":"฿฿","hours":"Mon-Fri 10:00-21:00, Sat-Sun 10:00-21:30","date_friendly":true,"night":true,"tags":["immersive","digital-art","new","photo"],"sources":["https://honeykidsasia.com/thailand/cave-fantasy-bangkok-review/","https://thesmartlocal.com/read/new-things-to-do-bangkok/","https://www.explera.co.th/blog/2026-07-13-bangkok-new-immersive-attractions-2026-agent-guide/"],"coord_confidence":"high"},{"id":110,"name":"Space & Time Cube+ Digital Art Museum","g":"museum","category":"art","area":"Bang Khae (Seacon Bangkae)","lat":13.7136,"lng":100.4084,"vibe":"27 themed rooms of projection-mapped digital art, the closest Bangkok gets to teamLab","tip":"Basement of Seacon Bangkae, a short walk from MRT Lak Song. From ฿199. Quiet walk-ins on weekdays","price":"฿฿","hours":"Mall hours ~10:00-21:00","date_friendly":true,"night":false,"tags":["immersive","digital-art","photo"],"sources":["https://www.timeout.com/bangkok/art/space-and-time-cube","https://thesmartlocal.com/read/new-things-to-do-bangkok/"],"coord_confidence":"medium"},{"id":111,"name":"Dib Bangkok","g":"museum","category":"art","area":"Sukhumvit 40 (Ekkamai/Phra Khanong)","lat":13.717,"lng":100.5815,"vibe":"Thailand's first international contemporary art museum, in a converted warehouse. On TIME's 2026 Greatest Places list","tip":"Thu-Mon only. ฿700 for foreigners. Current show 'Giving Life' features Calder mobiles (until May 2027)","price":"฿฿","hours":"Thu-Mon 10:00-19:00","date_friendly":true,"night":false,"tags":["contemporary-art","new","architecture"],"sources":["https://www.timeout.com/bangkok/art/dib-bangkok","https://www.timeout.com/bangkok/things-to-do/events-this-month"],"coord_confidence":"low"},{"id":112,"name":"Bangkok Art and Culture Centre (BACC) - Bangkok Art Biennale hub","g":"museum","category":"art","area":"Siam / National Stadium","lat":13.7468,"lng":100.5302,"vibe":"Spiral white gallery that hosts the Bangkok Art Biennale 'Angels and Mara' from 29 Oct 2026","tip":"Free entry, closed Mon. The Biennale runs to 28 Feb 2027 across BACC, Wat Arun, Wat Pho, Wat Prayoon and One Bangkok","price":"free","hours":"Tue-Sun 10:00-20:00","date_friendly":true,"night":false,"tags":["art","free","biennale"],"sources":["https://thebeat.asia/bangkok/the-list/whats-on/art-biennale-2026","https://www.tatnews.org/2026/05/tat-supports-bangkok-art-biennale-in-drive-to-elevate-bangkoks-global-art-profile/"],"coord_confidence":"high"},{"id":113,"name":"Bangkok Kunsthalle","g":"museum","category":"art","area":"Chinatown (Charoen Krung)","lat":13.7406,"lng":100.5111,"vibe":"Raw, burned-out former printing house turned gallery, with experimental shows, sound walks and Sunday cinema","tip":"Check bangkok-kunsthalle.org for performances and biweekly Sunday film nights. Combine with Chinatown food","price":"free","hours":"Varies by exhibition","date_friendly":true,"night":true,"tags":["contemporary-art","industrial","hidden","cinema"],"sources":["https://www.bkkartmag.com/articles/bangkok-arts-culture-weekly-guide-10-08-2026","https://artasiapacific.com/news/private-art-space-takes-over-factory-in-bangkok-s-chinatown"],"coord_confidence":"low"},{"id":114,"name":"MOCA - Museum of Contemporary Art","g":"museum","category":"art","area":"Chatuchak / Vibhavadi","lat":13.8536,"lng":100.5625,"vibe":"Huge private collection of trippy, surreal Thai art. The Thawan Duchanee halls are wild","tip":"Closed Mon. Allow 2h. Take a taxi from BTS Mo Chit. Good on a rainy afternoon","price":"฿","hours":"Tue-Sun 10:00-18:00","date_friendly":true,"night":false,"tags":["art","surreal","museum"],"sources":["https://citynomads.com/bangkoks-best-art-museums-from-buddhism-to-batman/"],"coord_confidence":"medium"},{"id":115,"name":"King Power Mahanakhon SkyWalk (glass floor)","g":"sight","category":"landmark","area":"Silom / Chong Nonsi","lat":13.7234,"lng":100.5285,"vibe":"Stand on a glass tray 310m up on the 78th floor. The pixelated 'Jenga' tower everyone films","tip":"Open until midnight, last entry 23:00. ฿1,000 before 15:30, ฿1,200 for sunset. The I-Tilt add-on tips you 65° over the edge","price":"฿฿฿","hours":"Daily 10:00-24:00","date_friendly":true,"night":true,"tags":["observation-deck","views","sunset","thrill"],"sources":["https://kingpowermahanakhon.co.th/skywalk/","https://thesmartlocal.com/read/new-things-to-do-bangkok/"],"coord_confidence":"high"},{"id":116,"name":"Akara Sky Hanuman (Bangkok Reflection), One City Centre","g":"sight","category":"landmark","area":"Ploenchit","lat":13.7429,"lng":100.5478,"vibe":"Bangkok's newest 360° mirrored observatory on floors 58-61, with light installations, a sky bar and Thai shows","tip":"Book the night SkyPass (19:00-22:00 entry), open until 02:00. Under-20s must leave by midnight. Skywalk from BTS Ploenchit","price":"฿฿฿","hours":"Daily 11:00-02:00","date_friendly":true,"night":true,"tags":["observation-deck","mirrors","new","sky-bar"],"sources":["https://www.klook.com/activity/192801-akara-sky-hanuman-ticket-bangkok/","https://www.kkday.com/en/product/609623","https://thesmartlocal.com/read/new-things-to-do-bangkok/"],"coord_confidence":"low"},{"id":117,"name":"Baiyoke Sky revolving roof deck","g":"sight","category":"landmark","area":"Pratunam","lat":13.7543,"lng":100.5404,"vibe":"Retro 84th-floor rotating outdoor deck with a buffet below. Cheesy and fun","tip":"Go around 22:00 when it's less crowded. Ticket includes a drink","price":"฿฿","hours":"Daily ~10:00-23:00","date_friendly":true,"night":true,"tags":["observation-deck","retro","views"],"sources":["https://lastminutejapan.com/en/baiyoke_sky_hotel_observation_deck"],"coord_confidence":"high"},{"id":118,"name":"Rajadamnern Stadium (live Muay Thai)","g":"show","category":"show","area":"Old Town (Ratchadamnoen)","lat":13.7576,"lng":100.507,"vibe":"The oldest Muay Thai stadium, with fights every night, a live pipe-and-drum band and a roaring crowd","tip":"Saturday is Rajadamnern World Series (19:00-22:00). Arrive 1h early. Ringside costs ฿1,500-4,500","price":"฿฿฿","hours":"Nightly ~18:00/19:00-22:00","date_friendly":true,"night":true,"tags":["muay-thai","live","sport","night"],"sources":["https://muaythaistadiums.com/rajadamnern-muay-thai-schedule/","https://rajadamnern.com/blog/crazy-things-to-do-in-bangkok/"],"coord_confidence":"high"},{"id":119,"name":"Lumpinee Boxing Stadium (Ram Intra)","g":"show","category":"show","area":"Ram Intra / Bang Khen","lat":13.869,"lng":100.6005,"vibe":"The other legendary Muay Thai stadium, rowdier and with more locals betting","tip":"Big cards on Friday and Saturday nights. Far north, so get a Grab. Cheaper back seats are where the gamblers are","price":"฿฿","hours":"Fight nights, evenings","date_friendly":true,"night":true,"tags":["muay-thai","live","sport","local"],"sources":["https://www.thaiholidayguide.com/watch-muay-thai-fights-thailand/"],"coord_confidence":"low"},{"id":120,"name":"Calypso Cabaret","g":"show","category":"show","area":"Asiatique (Charoen Krung)","lat":13.7047,"lng":100.5028,"vibe":"Bangkok's classic ladyboy cabaret: sequins, lip-sync, big comedy numbers","tip":"Warehouse 3. ฿900 online vs ฿1,200 at the door. Showtimes listed as 19:30/21:00 or 20:15/21:45, so check","price":"฿฿฿","hours":"Nightly ~19:30 & 21:00","date_friendly":true,"night":true,"tags":["cabaret","show","night","camp"],"sources":["https://touristbangkok.com/calypso-cabaret-bangkok/","https://sg.trip.com/things-to-do/detail/111499621/"],"coord_confidence":"medium"},{"id":121,"name":"Jurassic World: The Experience","g":"show","category":"show","area":"Asiatique (Charoen Krung)","lat":13.704,"lng":100.5038,"vibe":"Southeast Asia's first walk-through animatronic dino adventure, with life-size T-rex encounters","tip":"Timed entry, about 1.5-2h. Limited run, still open mid-2026, so confirm it's running before you book. Then the Ferris wheel","price":"฿฿฿","hours":"Timed sessions; Asiatique 16:00-24:00","date_friendly":true,"night":true,"tags":["immersive","animatronic","new"],"sources":["https://www.explera.co.th/blog/2026-07-13-bangkok-new-immersive-attractions-2026-agent-guide/","https://www.tagthai.com/explore/p/things-to-do-asiatique-the-riverfront"],"coord_confidence":"medium"},{"id":122,"name":"Khon masked dance at Sala Chalermkrung Royal Theatre","g":"show","category":"show","area":"Old Town (Wang Burapha)","lat":13.7443,"lng":100.4994,"vibe":"Ornate royal-epic masked dance in a 1933 art deco theatre","tip":"Check the schedule and book on Headout or Trazy. Show is about 1h. Sometimes cheaper with a Grand Palace ticket","price":"฿฿","hours":"Scheduled shows, check","date_friendly":true,"night":false,"tags":["culture","theatre","art-deco","traditional"],"sources":["https://www.headout.com/shows-and-entertainment-in-bangkok/khon-thai-show-at-sala-chalermkrung-royal-theater-e-12567","https://royalgrandpalace.th/en/attraction/khon"],"coord_confidence":"high"},{"id":123,"name":"Baan Silapin - Artist House puppet show","g":"show","category":"show","area":"Thonburi (Khlong Bang Luang)","lat":13.7365,"lng":100.4747,"vibe":"Free traditional Thai puppet show in a 200-year-old wooden house on a canal","tip":"Show around 14:00, closed Wed (check). Tip the troupe. Canal-side coffee and slow Thonburi vibes","price":"free","hours":"~9:00-18:00, puppets ~14:00","date_friendly":true,"night":false,"tags":["puppet","canal","traditional","hidden"],"sources":["https://en.wikipedia.org/wiki/Khlong_Bang_Luang_Artist_House","https://www.timeout.com/bangkok/things-to-do/baan-silapin","https://www.thaipbsworld.com/world/534999"],"coord_confidence":"medium"},{"id":124,"name":"Embassy Diplomat Screens (bed cinema)","g":"show","category":"show","area":"Ploenchit (Central Embassy)","lat":13.7437,"lng":100.5467,"vibe":"Ultra-luxe cinema with beds and private fridges, a personal server and free lounge snacks","tip":"6th floor, Central Embassy. From about ฿3,400 per bed, check the site for promos. Book a bed seat for date night","price":"฿฿฿฿","hours":"Daily, film times","date_friendly":true,"night":true,"tags":["cinema","luxury","bed","date"],"sources":["https://www.bkmagazine.com/city-living/bangkok-best-vip-cinemas/"],"coord_confidence":"high"},{"id":125,"name":"Enigma at Paragon Cineplex","g":"show","category":"show","area":"Siam (Siam Paragon)","lat":13.7462,"lng":100.5347,"vibe":"Sofa-bed seating with massage chairs, a full bar and butler service. A peak couple flex","tip":"6th floor, about ฿4,000 per couple including a meal. Honda Ultimate Screen (from ฿2,000) is the cheaper luxe option","price":"฿฿฿฿","hours":"Daily, film times","date_friendly":true,"night":true,"tags":["cinema","luxury","date"],"sources":["https://www.bkmagazine.com/city-living/bangkok-best-vip-cinemas/"],"coord_confidence":"high"},{"id":126,"name":"The Bed Cinema by Omazz (SF World, CentralWorld)","g":"show","category":"show","area":"Ratchaprasong (CentralWorld)","lat":13.7466,"lng":100.5393,"vibe":"Electric adjustable beds with built-in massage, the cheaper way to watch a movie lying down","tip":"7th floor, SF World. From about ฿1,300. MX4D with scent effects is next door if you want chaos","price":"฿฿฿","hours":"Daily, film times","date_friendly":true,"night":true,"tags":["cinema","bed","date"],"sources":["https://www.bkmagazine.com/city-living/bangkok-best-vip-cinemas/"],"coord_confidence":"high"},{"id":127,"name":"House Samyan (indie cinema)","g":"show","category":"show","area":"Sam Yan (Samyan Mitrtown)","lat":13.733,"lng":100.529,"vibe":"Bangkok's arthouse cinema for cult, festival and retro films","tip":"Check the schedule for themed retrospectives. Samyan Mitrtown is open 24h for food afterwards","price":"฿","hours":"Daily, film times","date_friendly":true,"night":true,"tags":["cinema","indie","arthouse"],"sources":["https://thesmartlocal.com/thailand/alternative-theatres-in-bangkok","https://bk.asia-city.com/node/118286"],"coord_confidence":"medium"},{"id":128,"name":"Lido Connect","g":"show","category":"show","area":"Siam Square","lat":13.7456,"lng":100.533,"vibe":"Old Lido cinema turned creative venue for indie gigs, small theatre, drag nights and screenings","tip":"Check the Lido Connect page for weekly events. Easy to combine with a Siam Square night out","price":"฿","hours":"Event-based","date_friendly":true,"night":true,"tags":["indie","live","theatre","creative"],"sources":["https://thesmartlocal.com/thailand/alternative-theatres-in-bangkok"],"coord_confidence":"medium"},{"id":129,"name":"Wat Pariwat (\"David Beckham\" temple)","g":"sight","category":"temple","area":"Rama 3 / Yan Nawa","lat":13.6905,"lng":100.5432,"vibe":"Hand-carved Pikachu, superheroes, chainsaw monks and a David Beckham carving on the altar","tip":"Free. Take the BRT from Sathorn. Bring your zoom lens and hunt for the hidden pop-culture figures. About 45 minutes","price":"free","hours":"Daily ~8:00-17:00","date_friendly":true,"night":false,"tags":["weird","temple","pop-culture","photo"],"sources":["https://www.odditycentral.com/travel/bangkoks-david-beckham-temple-is-one-of-the-worlds-weirdest-religious-buildings.html","https://differentville.com/?p=4508","https://differentville.com/?p=7999"],"coord_confidence":"low"},{"id":130,"name":"Wat Paknam Phasi Charoen (Giant Buddha & glass stupa)","g":"sight","category":"temple","area":"Phasi Charoen","lat":13.7218,"lng":100.47,"vibe":"A 69m golden Buddha plus a stupa with a psychedelic glass universe ceiling. Huge on TikTok","tip":"Go up to the top floor of the white stupa for the green glass ceiling. Free. MRT Bang Phai or a canal boat","price":"free","hours":"Daily ~8:00-18:00","date_friendly":true,"night":false,"tags":["temple","psychedelic","photo","giant"],"sources":["https://www.khaosodenglish.com/featured/2026/08/17/discover-the-giant-buddha-at-bangkoks-wat-paknam/amp/","https://theo-courant.com/en/bangkok-wat-paknam-giant-buddha/","https://differentville.com/?p=7999"],"coord_confidence":"high"},{"id":131,"name":"Wat Yannawa (Boat Temple)","g":"sight","category":"temple","area":"Sathorn / Saphan Taksin","lat":13.7189,"lng":100.5139,"vibe":"19th-century temple shaped like a Chinese junk ship, with a view of the abandoned Ghost Tower","tip":"Two minutes from BTS Saphan Taksin. Free. Combine with the Ghost Tower view and a riverside sunset","price":"free","hours":"Daily daytime","date_friendly":true,"night":false,"tags":["temple","quirky","boat"],"sources":["https://differentville.com/?p=7999"],"coord_confidence":"high"},{"id":132,"name":"Wat Chakrawat (Crocodile Temple)","g":"sight","category":"temple","area":"Chinatown (Sampanthawong)","lat":13.7406,"lng":100.5045,"vibe":"Chinatown temple with a pool of crocodiles, tied to a legend of a man-eating croc the monks took in","tip":"MRT Sam Yot or Ratchawong pier. Free. Combine with Yaowarat street food after dark","price":"free","hours":"Daily daytime","date_friendly":true,"night":false,"tags":["temple","weird","animals","hidden"],"sources":["https://differentville.com/?p=7999"],"coord_confidence":"medium"},{"id":133,"name":"Wat Prayoon (turtle mound) - Biennale venue","g":"sight","category":"temple","area":"Thonburi (Memorial Bridge)","lat":13.7381,"lng":100.496,"vibe":"Riverside temple with a man-made 'turtle mountain' full of turtles, hosting Biennale art from 29 Oct","tip":"Walk across Memorial Bridge or the Phra Pokklao Sky Park. Turtle mound area opens daytime only","price":"free","hours":"Daily ~8:00-18:00","date_friendly":true,"night":false,"tags":["temple","quirky","biennale","art"],"sources":["https://thebeat.asia/bangkok/the-list/whats-on/art-biennale-2026"],"coord_confidence":"medium"},{"id":134,"name":"Wat Saket (Golden Mount)","g":"sight","category":"temple","area":"Old Town (Pom Prap)","lat":13.7538,"lng":100.5067,"vibe":"Climb 300+ steps past gongs and misty waterfalls to a golden chedi with 360° old-city views","tip":"Go 1h before sunset. Small foreigner fee. Huge temple fair with rides and food in November","price":"฿","hours":"Daily ~7:00-19:00","date_friendly":true,"night":false,"tags":["temple","views","sunset"],"sources":["https://www.timeout.com/bangkok/things-to-do/events-this-month"],"coord_confidence":"high"},{"id":135,"name":"Wat Arun (Temple of Dawn)","g":"sight","category":"temple","area":"Thonburi (Wat Arun)","lat":13.7437,"lng":100.4888,"vibe":"Spire covered in porcelain from old shipwrecks. Lit gold at night and a Biennale venue from Oct 29","tip":"Visit in the day, then watch it lit up from a rooftop bar across the river around 19:00. ฿200 entry","price":"฿","hours":"Daily 8:00-18:00","date_friendly":true,"night":true,"tags":["temple","iconic","biennale","night-view"],"sources":["https://www.atlasobscura.com/things-to-do/bangkok-thailand","https://thebeat.asia/bangkok/the-list/whats-on/art-biennale-2026"],"coord_confidence":"high"},{"id":136,"name":"Erawan Museum (giant three-headed elephant)","g":"museum","category":"museum","area":"Samut Prakan (Bang Mueang)","lat":13.6297,"lng":100.5876,"vibe":"A 29m three-headed copper elephant you walk inside, up to a cosmic stained-glass dome","tip":"BTS Chang Erawan. Allow 1.5h. Combine with Ancient City for a full-day trip","price":"฿฿","hours":"Daily 9:00-19:00","date_friendly":true,"night":false,"tags":["weird","giant","stained-glass","photo"],"sources":["https://differentville.com/?p=7999","https://www.thaiholidayguide.com/attraction/erawan-museum/"],"coord_confidence":"high"},{"id":137,"name":"Ancient City (Muang Boran)","g":"sight","category":"landmark","area":"Samut Prakan","lat":13.5389,"lng":100.6262,"vibe":"Huge open-air park of 100+ replica Thai palaces and temples. Rent a golf cart or bike","tip":"Go after 15:00 when it's cooler (open until 19:00). Rent an e-cart. Allow 3h+","price":"฿฿","hours":"Daily 9:00-19:00","date_friendly":true,"night":false,"tags":["open-air","heritage","bike","date"],"sources":["https://www.headout.com/ancient-siam/ancient-city-tickets-with-free-audio-e-11795/"],"coord_confidence":"medium"},{"id":138,"name":"Sathorn Unique Tower (\"Ghost Tower\")","g":"sight","category":"landmark","area":"Sathorn / Saphan Taksin","lat":13.7206,"lng":100.5137,"vibe":"Unfinished 1990s skyscraper left to rot since the Asian financial crisis, Bangkok's eeriest skyline sight","tip":"Entry is illegal and guarded. View it from Wat Yannawa or the river pier at dusk","price":"free","hours":"View from outside","date_friendly":true,"night":true,"tags":["abandoned","eerie","urbex-view"],"sources":["https://rajadamnern.com/blog/crazy-things-to-do-in-bangkok/","https://differentville.com/?p=7999"],"coord_confidence":"high"},{"id":139,"name":"Robot Building","g":"sight","category":"landmark","area":"Sathorn","lat":13.7215,"lng":100.527,"vibe":"1986 postmodern office tower built to look like a giant cartoon robot, eyes and antennae included","tip":"Photo stop only, 5 minutes. Walk from BTS Surasak or Chong Nonsi on the way to Mahanakhon","price":"free","hours":"View from outside","date_friendly":true,"night":false,"tags":["quirky","architecture","photo"],"sources":["https://www.atlasobscura.com/things-to-do/bangkok-thailand"],"coord_confidence":"medium"},{"id":140,"name":"Phra Pokklao Sky Park","g":"sight","category":"landmark","area":"Old Town / Memorial Bridge","lat":13.7393,"lng":100.4985,"vibe":"Elevated park built on an abandoned skytrain bridge over the Chao Phraya, great for sunsets","tip":"Free. Go at sunset, then walk to Wat Prayoon or Pak Khlong flower market","price":"free","hours":"Daily ~5:00-20:00","date_friendly":true,"night":false,"tags":["views","sunset","free","date"],"sources":["https://www.atlasobscura.com/things-to-do/bangkok-thailand"],"coord_confidence":"medium"},{"id":141,"name":"Tha Prachan Amulet Market","g":"sight","category":"landmark","area":"Old Town (Tha Prachan)","lat":13.7555,"lng":100.49,"vibe":"Alleys of collectors inspecting magic amulets with loupes. Strange, intense and very local","tip":"Mornings to early afternoon, busiest on weekends. Free to browse. Then grab food by the river","price":"free","hours":"Daily ~8:00-17:00","date_friendly":true,"night":false,"tags":["weird","market","spiritual","local"],"sources":["https://www.atlasobscura.com/things-to-do/bangkok-thailand"],"coord_confidence":"high"},{"id":142,"name":"Museum Siam (Discovery Museum)","g":"museum","category":"museum","area":"Old Town (Tha Tien)","lat":13.7442,"lng":100.4943,"vibe":"Playful interactive museum on 'what is Thai'. Also a Biennale venue from 29 Oct 2026","tip":"Closed Mon. Allow 1.5h. Next to Wat Pho, so pair it with a riverside dinner","price":"฿","hours":"Tue-Sun 10:00-18:00","date_friendly":true,"night":false,"tags":["interactive","culture","biennale"],"sources":["https://thebeat.asia/bangkok/the-list/whats-on/art-biennale-2026"],"coord_confidence":"high"},{"id":143,"name":"Jim Thompson House","g":"museum","category":"museum","area":"Siam / National Stadium","lat":13.7493,"lng":100.5283,"vibe":"A spy-turned-silk-king's jungly teak house, and the mystery of how he vanished in 1967","tip":"Guided tours only (about 35 minutes). The bar and restaurant are nice for drinks after","price":"฿","hours":"Daily 10:00-18:00","date_friendly":true,"night":false,"tags":["heritage","mystery","garden"],"sources":["https://citynomads.com/bangkoks-best-art-museums-from-buddhism-to-batman/"],"coord_confidence":"high"},{"id":144,"name":"Bangkokian Museum","g":"museum","category":"museum","area":"Bang Rak (Charoen Krung)","lat":13.7269,"lng":100.5157,"vibe":"A family's 1930s home left frozen in time: old radios, kitchens, and a doctor's surgery","tip":"Free (donation), closed Mon-Tue. 30-45 minutes. Walk on to Warehouse 30 and Charoen Krung cafes","price":"free","hours":"Wed-Sun 10:00-16:00","date_friendly":true,"night":false,"tags":["heritage","time-capsule","free","hidden"],"sources":["https://www.timeout.com/bangkok/museums/bangkoks-strangest-museums-and-attractions"],"coord_confidence":"medium"},{"id":145,"name":"Warehouse 30","g":"museum","category":"art","area":"Bang Rak (Charoen Krung)","lat":13.726,"lng":100.5145,"vibe":"WWII-era warehouses turned design shops, galleries and pop-up exhibitions in the creative district","tip":"Late afternoon is best. Charoen Krung street art and Talat Noi are walkable","price":"free","hours":"Daily ~11:00-20:00","date_friendly":true,"night":false,"tags":["art","creative","design"],"sources":["https://www.atlasobscura.com/things-to-do/bangkok-thailand"],"coord_confidence":"medium"},{"id":146,"name":"Talat Noi street art & So Heng Tai Mansion","g":"museum","category":"art","area":"Talat Noi (Chinatown)","lat":13.7334,"lng":100.5134,"vibe":"Rusting car-part alleys covered in murals, plus a 200-year-old Chinese mansion with a koi-filled dive pool","tip":"Go late afternoon. So Heng Tai has a small café fee. Riverside bars nearby for sunset","price":"free","hours":"Daytime","date_friendly":true,"night":false,"tags":["street-art","heritage","hidden","photo"],"sources":["https://www.atlasobscura.com/things-to-do/bangkok-thailand"],"coord_confidence":"medium"},{"id":147,"name":"Neilson Hays Library","g":"sight","category":"landmark","area":"Silom / Surawong","lat":13.7258,"lng":100.5318,"vibe":"Domed 1921 library with a garden café. Feels like a hidden colonial time warp","tip":"Closed Mon. Small entry fee for non-members. Rotunda gallery hosts art shows","price":"฿","hours":"Tue-Sun 9:30-17:00","date_friendly":true,"night":false,"tags":["heritage","library","quiet","hidden"],"sources":["https://www.atlasobscura.com/things-to-do/bangkok-thailand"],"coord_confidence":"medium"},{"id":148,"name":"Museum of Floral Culture","g":"museum","category":"museum","area":"Dusit","lat":13.788,"lng":100.5145,"vibe":"Teak house and garden devoted to Asian flower art. Calm, pretty and a good date spot","tip":"Book a tour, allow 1h. Tea in the garden afterwards","price":"฿","hours":"Tue-Sun 10:00-18:00","date_friendly":true,"night":false,"tags":["garden","heritage","calm","date"],"sources":["https://citynomads.com/bangkoks-best-art-museums-from-buddhism-to-batman/"],"coord_confidence":"low"},{"id":149,"name":"Jodd Fairs Ratchada","g":"market","category":"market","area":"Ratchada / Din Daeng","lat":13.766,"lng":100.5701,"vibe":"Neon night market with TikTok-famous 'volcano' leng saep ribs, bars and live music","tip":"MRT Thailand Cultural Centre Exit 4. Go after 7pm and bring cash. Pairs with Train Night Market next door","price":"฿","hours":"Daily 17:00-01:00","date_friendly":true,"night":true,"tags":["night-market","street-food","date-night"],"sources":["https://www.phuket101.net/best-night-markets-in-bangkok/","https://en.itravelblog.net/bangkok-night-market/"],"coord_confidence":"medium"},{"id":150,"name":"Train Night Market Ratchada","g":"market","category":"market","area":"Ratchada / Din Daeng","lat":13.7656,"lng":100.5693,"vibe":"Reopened Mar 2026 on the old colourful-tent lot. Retro stalls, cheap beer and the classic rooftop-view photo","tip":"Behind Esplanade, MRT Thailand Cultural Centre Exit 3. Check their FB page before a Monday visit","price":"฿","hours":"Daily 17:00-01:00 (some say Tue-Sun)","date_friendly":true,"night":true,"tags":["night-market","retro","street-food"],"sources":["https://www.phuket101.net/bangkok/train-night-market-ratchada/","https://www.phuket101.net/best-night-markets-in-bangkok/"],"coord_confidence":"medium"},{"id":151,"name":"Liab Duan Danneramit Night Market","g":"market","category":"market","area":"Chatuchak / Lat Phrao","lat":13.82057,"lng":100.56501,"vibe":"Night market at Thailand's first theme park, with a fairytale castle, ฿30 carnival rides and BTS trains going past","tip":"BTS Phahon Yothin 24 Exit 2, about a 5-min walk. Ride the Viking and go up to the castle balcony","price":"฿","hours":"Daily ~16:00-24:00","date_friendly":true,"night":true,"tags":["night-market","carnival","photo-spot"],"sources":["https://thesmartlocal.com/read/liab-duan-danneramit-night-market-bangkok/amp/","https://thesmartlocal.com/read/new-things-to-do-bangkok/"],"coord_confidence":"high"},{"id":152,"name":"Chatuchak Weekend Market","g":"market","category":"market","area":"Chatuchak","lat":13.7999,"lng":100.5507,"vibe":"15,000+ stalls of vintage, sneakers, plants, art and coconut ice cream. You will get lost, which is part of it","tip":"Get there by 10am before it gets hot. Fri night has a 6pm-midnight market. BTS Mo Chit / MRT Chatuchak Park","price":"฿","hours":"Sat-Sun 09:00-18:00; Fri 18:00-24:00","date_friendly":true,"night":false,"tags":["market","vintage","shopping","weekend"],"sources":["https://www.phuket101.net/best-night-markets-in-bangkok/","https://www.lonelyplanet.com/thailand/bangkok/greater-bangkok/attractions/chatuchak-weekend-market/a/poi-sig/407334/1324184"],"coord_confidence":"high"},{"id":153,"name":"Talad Rot Fai Srinakarin","g":"market","category":"market","area":"Prawet / Srinakarin","lat":13.6915,"lng":100.651,"vibe":"The original vintage train market: classic cars, antiques, retro bars and huge food rows","tip":"Far out, so take a Grab or the Yellow Line. Weekend nights are busiest. Behind Seacon Square","price":"฿","hours":"Thu-Sun 17:00-01:00","date_friendly":true,"night":true,"tags":["night-market","vintage","retro","antiques"],"sources":["https://www.phuket101.net/best-night-markets-in-bangkok/","https://en.itravelblog.net/bangkok-night-market/"],"coord_confidence":"medium"},{"id":154,"name":"Chang Chui Creative Park","g":"market","category":"market","area":"Bang Phlat (Thonburi)","lat":13.7864,"lng":100.48,"vibe":"Hipster market built around a decommissioned airliner, with art, bars, a theatre and DIY shops","tip":"Grab only. Weekends are livelier and weekdays are quiet. Closed Wednesdays","price":"฿","hours":"16:00-23:00, closed Wed","date_friendly":true,"night":true,"tags":["market","art","quirky","photo-spot"],"sources":["https://www.phuket101.net/best-night-markets-in-bangkok/","https://en.itravelblog.net/bangkok-night-market/"],"coord_confidence":"medium"},{"id":155,"name":"Siam Gypsy Junction","g":"market","category":"market","area":"Bang Sue / Bang Son","lat":13.8197,"lng":100.532,"vibe":"Gritty second-hand and vintage market under a railway viaduct, with an old locomotive at the gate","tip":"MRT Purple Line Bang Son, opposite the exit. Go Wed-Sun evenings and haggle for antiques","price":"฿","hours":"Wed-Sun 17:00-01:00","date_friendly":false,"night":true,"tags":["night-market","vintage","local","off-the-beaten-path"],"sources":["https://en.itravelblog.net/bangkok-night-market/","https://en.wikipedia.org/wiki/Siam_Gypsy_Junction"],"coord_confidence":"medium"},{"id":156,"name":"Khlong Ong Ang Walking Street","g":"market","category":"market","area":"Old Town / Sam Yot","lat":13.7455,"lng":100.5003,"vibe":"Canal-side walking street with murals, lanterns, kayaks and food carts. Feels like a mini Venice at dusk","tip":"Weekends only. MRT Sam Yot. Combine with Chinatown street food after","price":"free","hours":"Fri-Sun 16:00-22:00","date_friendly":true,"night":true,"tags":["market","canal","street-art","date-night"],"sources":["https://www.phuket101.net/best-night-markets-in-bangkok/"],"coord_confidence":"high"},{"id":157,"name":"Asiatique The Riverfront","g":"market","category":"market","area":"Charoen Krung / Riverside","lat":13.7044,"lng":100.5035,"vibe":"Riverside warehouse market with a big Ferris wheel and river breeze. Touristy, but a reliable date spot","tip":"Free shuttle boat from Sathorn Pier 4-11:30pm. Ride the Ferris wheel at sunset","price":"฿฿","hours":"Daily ~16:00-24:00","date_friendly":true,"night":true,"tags":["market","riverside","ferris-wheel","date-night"],"sources":["https://www.phuket101.net/best-night-markets-in-bangkok/","https://en.itravelblog.net/bangkok-night-market/"],"coord_confidence":"high"},{"id":158,"name":"Skyflyers: Wings of Garudapterus","g":"activity","category":"activity","area":"Asiatique / Riverside","lat":13.704,"lng":100.5042,"vibe":"Asia-Pacific's tallest swing ride at 135m, spinning you out over the Chao Phraya","tip":"Go after dark for the city lights. Tickets from ~฿320","price":"฿฿","hours":"Daily 13:00-22:00","date_friendly":true,"night":true,"tags":["adventure","thrill","views","riverside"],"sources":["https://thesmartlocal.com/read/new-things-to-do-bangkok/","https://gothaitransport.com/new-things-to-do-in-bangkok/"],"coord_confidence":"medium"},{"id":159,"name":"Pak Khlong Talat Flower Market","g":"market","category":"market","area":"Phra Nakhon / Saphan Phut","lat":13.7428,"lng":100.4963,"vibe":"24-hour flower market. Mountains of marigolds and roses under fluorescent light, best after midnight","tip":"Go 10pm-3am for peak trading. Buy a cheap bouquet for your date","price":"free","hours":"24 hours","date_friendly":true,"night":true,"tags":["market","late-night","photo-spot","local"],"sources":["https://en.itravelblog.net/bangkok-night-market/"],"coord_confidence":"high"},{"id":160,"name":"Huai Khwang Night Market","g":"market","category":"market","area":"Huai Khwang","lat":13.7787,"lng":100.5737,"vibe":"Very local late-night food strip running till 5am, with Chinese-style hotpot and noodles. Few tourists","tip":"MRT Huai Khwang, right by the exit. Best spot for a post-club 2am feed","price":"฿","hours":"Daily ~20:00-05:00","date_friendly":false,"night":true,"tags":["night-market","street-food","late-night","local"],"sources":["https://en.itravelblog.net/bangkok-night-market/"],"coord_confidence":"medium"},{"id":161,"name":"Patpong Night Market","g":"market","category":"market","area":"Silom","lat":13.7286,"lng":100.5332,"vibe":"Knock-off market in the middle of the neon red-light strip. Chaotic people-watching","tip":"BTS Sala Daeng. Haggle hard, starting at around 40% of the asking price","price":"฿","hours":"Daily 17:00-24:00","date_friendly":false,"night":true,"tags":["night-market","nightlife","neon"],"sources":["https://www.phuket101.net/best-night-markets-in-bangkok/"],"coord_confidence":"high"},{"id":162,"name":"Lhong 1919","g":"experience","category":"experience","area":"Khlong San (Thonburi riverside)","lat":13.7354,"lng":100.5104,"vibe":"Restored 1850s Chinese trading pier with a shrine, murals, cafes and river views. Very photogenic","tip":"Best late afternoon. Cross by ferry from the Si Phraya side. Closes 8pm","price":"free","hours":"Daily 08:00-20:00","date_friendly":true,"night":false,"tags":["heritage","riverside","photo-spot","cafes"],"sources":["https://en.itravelblog.net/bangkok-night-market/"],"coord_confidence":"high"},{"id":163,"name":"ICONSIAM","g":"shop","category":"mall","area":"Khlong San (riverside)","lat":13.7266,"lng":100.5103,"vibe":"Riverside mega-mall with an indoor floating market (SookSiam) and a nightly fountain show","tip":"Take the free shuttle boat from Sathorn Pier. Fountain show runs in the evenings on the river terrace","price":"฿฿","hours":"Daily 10:00-22:00","date_friendly":true,"night":false,"tags":["mall","riverside","rainy-day","food"],"sources":["https://thesmartlocal.com/read/shopping-malls-bangkok/","https://thesmartlocal.com/read/new-things-to-do-bangkok/"],"coord_confidence":"high"},{"id":164,"name":"POP MART Global Landmark Store","g":"shop","category":"shop","area":"ICONSIAM","lat":13.7268,"lng":100.5105,"vibe":"Said to be the world's biggest POP MART, with Labubu shrines, a cafe and blind-box roulette","tip":"7th floor of ICONSIAM. Weekday mornings mean fewer Labubu hunters","price":"฿฿","hours":"Daily 10:00-22:00","date_friendly":true,"night":false,"tags":["toys","collectibles","rainy-day"],"sources":["https://thesmartlocal.com/read/new-things-to-do-bangkok/","https://gothaitransport.com/new-things-to-do-in-bangkok/"],"coord_confidence":"medium"},{"id":165,"name":"Haus Nowhere Bangkok","g":"shop","category":"shop","area":"ICONSIAM","lat":13.7264,"lng":100.5101,"vibe":"Gentle Monster group's art-installation concept store. Weird sculptures plus eyewear and Tamburins","tip":"Free to walk in. Good for photos. Pairs with POP MART in the same complex","price":"free","hours":"Daily 10:00-22:00","date_friendly":true,"night":false,"tags":["concept-store","art","photo-spot","rainy-day"],"sources":["https://thesmartlocal.com/read/new-things-to-do-bangkok/","https://gothaitransport.com/new-things-to-do-in-bangkok/"],"coord_confidence":"medium"},{"id":166,"name":"Central Park (Dusit Central Park) & Rooftop Garden","g":"shop","category":"mall","area":"Silom / Rama IV","lat":13.7299,"lng":100.537,"vibe":"New mall (Sept 2025) topped by Thailand's biggest rooftop garden: waterfalls, trails and Lumpini views","tip":"MRT Silom / BTS Sala Daeng. Sunset on the roof, then Parkside Market (Michelin vendors) on LG","price":"฿฿","hours":"Daily 10:00-22:00","date_friendly":true,"night":false,"tags":["mall","rooftop","garden","new"],"sources":["https://www.phuket101.net/bangkok/central-park-bangkok/","https://www.nationthailand.com/business/property/40054189"],"coord_confidence":"high"},{"id":167,"name":"Lumpini Park","g":"park","category":"park","area":"Lumphini / Silom","lat":13.7314,"lng":100.5414,"vibe":"Bangkok's Central Park, with paddle boats, skyline views and giant monitor lizards strolling by","tip":"Free. Go 5-7pm when it cools down. Rent a swan boat on the lake","price":"free","hours":"Daily 04:30-22:00","date_friendly":true,"night":false,"tags":["park","outdoors","lizards","free"],"sources":["https://www.timeout.com/bangkok/attractions/best-public-parks-in-bangkok","https://www.phuket101.net/bangkok/central-park-bangkok/"],"coord_confidence":"high"},{"id":168,"name":"Benjakitti Forest Park","g":"park","category":"park","area":"Khlong Toei / Asok","lat":13.73,"lng":100.559,"vibe":"Wetland forest park with elevated skywalks and skyline reflections in the lake","tip":"Rent a bike and loop the skywalk around golden hour. Walkable from MRT QSNCC","price":"free","hours":"Daily ~05:00-22:00","date_friendly":true,"night":false,"tags":["park","skywalk","sunset","cycling"],"sources":["https://www.timeout.com/bangkok/attractions/best-public-parks-in-bangkok"],"coord_confidence":"high"},{"id":169,"name":"Bang Krachao & Sri Nakhon Khuean Khan Park","g":"park","category":"park","area":"Bang Krachao (Phra Pradaeng)","lat":13.6866,"lng":100.556,"vibe":"Bangkok's 'green lung': a jungle island across the river with bike paths on raised walkways","tip":"฿10-20 boat from Wat Khlong Toei Nok pier. Bikes ฿40-80/day. Weekend floating market","price":"฿","hours":"Park 05:00-19:00","date_friendly":true,"night":false,"tags":["cycling","nature","day-trip","adventure"],"sources":["https://www.bucketlistly.blog/posts/bang-krachao-travel-guide-things-to-do","https://www.timeout.com/bangkok/attractions/best-public-parks-in-bangkok"],"coord_confidence":"medium"},{"id":170,"name":"Chulalongkorn Centenary Park","g":"park","category":"park","area":"Samyan","lat":13.7393,"lng":100.5245,"vibe":"Sloped, award-winning design park built as a flood sponge. Locals picnic on the grass roof","tip":"Combine with Samyan Mitrtown, which has 24h food courts. Best at dusk","price":"free","hours":"Daily ~05:00-22:00","date_friendly":true,"night":false,"tags":["park","design","picnic"],"sources":["https://www.timeout.com/bangkok/attractions/best-public-parks-in-bangkok"],"coord_confidence":"high"},{"id":171,"name":"Terminal 21 Asok","g":"shop","category":"mall","area":"Asok / Sukhumvit","lat":13.7377,"lng":100.5604,"vibe":"Airport-themed mall where every floor is a city (Tokyo, London, SF) and the toilets are a must-see","tip":"BTS Asok / MRT Sukhumvit. Pier 21 food court on 5F is very cheap and good","price":"฿","hours":"Daily 10:00-22:00","date_friendly":true,"night":false,"tags":["mall","themed","cheap-eats","rainy-day"],"sources":["https://thesmartlocal.com/read/shopping-malls-bangkok/"],"coord_confidence":"high"},{"id":172,"name":"Donki Mall Thonglor","g":"shop","category":"mall","area":"Thonglor / Ekkamai","lat":13.7329,"lng":100.5829,"vibe":"Mini Japan: 24h Don Don Donki chaos, Japanese street food and snacks you've never heard of","tip":"Open 24h. Great for a late-night snack run after Thonglor bars","price":"฿","hours":"Donki 24 hours","date_friendly":true,"night":true,"tags":["japanese","24h","snacks","shopping"],"sources":["https://www.timeout.com/bangkok/shopping/donki-mall-thonglor","https://thesmartlocal.com/thailand/new-don-don-donki/"],"coord_confidence":"medium"},{"id":173,"name":"EmSphere & TRIBE Sky Beach Club","g":"shop","category":"mall","area":"Phrom Phong / Sukhumvit","lat":13.73,"lng":100.5675,"vibe":"Newest EM District mall with a city IKEA, IMAX and a rooftop 'beach' club with sunset parties","tip":"BTS Phrom Phong skywalk. Head to the rooftop TRIBE for sunset drinks, then a concert in the hall","price":"฿฿","hours":"Daily 10:00-22:00 (rooftop later)","date_friendly":true,"night":true,"tags":["mall","rooftop","sunset","nightlife"],"sources":["https://www.phuket101.net/emsphere-shopping-mall-in-bangkok-sukhumvit/","https://en.wikipedia.org/wiki/EmSphere"],"coord_confidence":"medium"},{"id":174,"name":"Playerbox Siam Discovery (E-Gokart & Arcade)","g":"activity","category":"activity","area":"Siam","lat":13.7466,"lng":100.5315,"vibe":"Air-conditioned indoor e-go-kart track, 40+ arcade machines, a VR paraglider and a private karaoke box","tip":"4F Siam Discovery, BTS Siam. Klook combo packs are cheaper. Reviews current to 2026","price":"฿฿","hours":"Daily ~10:00-22:00","date_friendly":true,"night":false,"tags":["go-kart","arcade","vr","karaoke","rainy-day"],"sources":["https://www.klook.com/en-SG/activity/165823-playerbox-indoor-e-gokart-track-game-arcade-at-siam-discovery/"],"coord_confidence":"high"},{"id":175,"name":"Hirono Floating Market Store","g":"shop","category":"shop","area":"Siam Square","lat":13.7448,"lng":100.5339,"vibe":"POP MART's Hirono flagship themed as a floating market, with a cafe and gallery","tip":"Siam Square Soi 7. Pair it with vintage digging at Blulagoon (Siam Sq Soi 2)","price":"฿฿","hours":"Daily 10:00-22:00","date_friendly":true,"night":false,"tags":["toys","collectibles","themed-store"],"sources":["https://thesmartlocal.com/read/new-things-to-do-bangkok/","https://gothaitransport.com/new-things-to-do-in-bangkok/"],"coord_confidence":"medium"},{"id":176,"name":"Playsquare Laser Tag CentralWorld","g":"activity","category":"activity","area":"Ratchaprasong","lat":13.7466,"lng":100.5393,"vibe":"Neon laser-tag arena with 20+ game modes. Competitive and silly date energy","tip":"2F CentralWorld. ~฿350/person. Also a branch at Central EastVille","price":"฿฿","hours":"Daily 11:00-20:00","date_friendly":true,"night":false,"tags":["laser-tag","indoor","rainy-day","group"],"sources":["https://thesmartlocal.com/read/indoor-things-to-do-bangkok/amp/"],"coord_confidence":"high"},{"id":177,"name":"EasyKart RCA Plaza","g":"activity","category":"activity","area":"RCA / Huai Khwang","lat":13.7505,"lng":100.5765,"vibe":"Real indoor go-kart track with fast 200cc karts. Race your date, then hit RCA clubs next door","tip":"~฿1,499 adult (Klook cheaper). Open until 11pm Fri-Sun. Grab there, since no BTS nearby","price":"฿฿฿","hours":"Mon-Thu 13:00-21:00; Fri-Sun 13:00-23:00","date_friendly":true,"night":true,"tags":["go-kart","adventure","indoor"],"sources":["https://thesmartlocal.com/read/indoor-things-to-do-bangkok/amp/","https://www.klook.com/activity/12684-indoor-go-karting-experience-easykart-bangkok/"],"coord_confidence":"medium"},{"id":178,"name":"BOUNCE Trampoline Park EmQuartier","g":"activity","category":"activity","area":"Phrom Phong","lat":13.7317,"lng":100.5698,"vibe":"Big trampoline park with slam-dunk lanes, a wall-run zone and a giant air bag","tip":"~฿470/adult. Grip socks required. Weekday afternoons are quieter","price":"฿฿","hours":"Opens 11:00 weekdays, 10:00 weekends","date_friendly":true,"night":false,"tags":["trampoline","active","rainy-day"],"sources":["https://www.ticket2attraction.com/discount-tickets/bounce/","https://www.timeout.com/bangkok/things-to-do/the-ultimate-list-of-bangkoks-indoor-actvities"],"coord_confidence":"high"},{"id":179,"name":"Golden Axe Throw Club","g":"activity","category":"activity","area":"Lat Phrao","lat":13.827,"lng":100.5975,"vibe":"Bangkok's original axe-throwing range, with beers and wooden targets","tip":"~฿500/person/hr, unlimited axes. Status not confirmed for 2026, so check their IG/FB before going","price":"฿฿","hours":"Tue-Sun 16:00-23:00","date_friendly":true,"night":true,"tags":["axe-throwing","adventure","group"],"sources":["https://www.timeout.com/bangkok/things-to-do/the-ultimate-list-of-bangkoks-indoor-actvities","https://lokalee.app/en/tours/1-hour-axe-throwing-experience"],"coord_confidence":"low"},{"id":180,"name":"Stonegoat Climbing Gym","g":"activity","category":"activity","area":"Phra Khanong / Sukhumvit 69","lat":13.7185,"lng":100.594,"vibe":"Warehouse bouldering gym with a friendly expat crowd and good beginner walls","tip":"Day pass ฿300 weekdays / ฿450 weekends, shoes from ฿100. Open till 10pm. Branch at The PARQ too","price":"฿","hours":"Daily 10:00-22:00","date_friendly":true,"night":true,"tags":["climbing","bouldering","active","rainy-day"],"sources":["https://www.timeout.com/bangkok/sports-and-fitness/bangkoks-top-4-climbing-gyms","https://www.timeout.com/bangkok/sports-and-fitness/stonegoat-climbing-gym"],"coord_confidence":"low"},{"id":181,"name":"Urban Playground Climbing","g":"activity","category":"activity","area":"Sukhumvit 49 / Phrom Phong","lat":13.734,"lng":100.5785,"vibe":"Rope and boulder walls inside The Racquet Club. The proper intro-to-climbing spot","tip":"฿495 weekday / ฿595 weekend day pass. Gear rental ฿150+","price":"฿฿","hours":"Mon-Fri 12-22; Sat-Sun 9-21","date_friendly":true,"night":true,"tags":["climbing","active","indoor"],"sources":["https://www.timeout.com/bangkok/sports-and-fitness/bangkoks-top-4-climbing-gyms","https://www.timeout.com/bangkok/sports-and-fitness/urban-playground-climbing"],"coord_confidence":"medium"},{"id":182,"name":"Flow House Bangkok","g":"activity","category":"activity","area":"Sukhumvit 26 / Phrom Phong","lat":13.7233,"lng":100.569,"vibe":"FlowRider surf wave in A-Square with a poolside bar. Wipe out, then have a beer","tip":"~US$27 per session. Hours vary by season, so check flowhousethailand.com. Last entry 1hr before close","price":"฿฿฿","hours":"~11:00-21:00","date_friendly":true,"night":false,"tags":["surf","adventure","water"],"sources":["https://m.waug.com/en/activities/126275","https://www.headout.com/nl/flow-house-surf-experience-kaartjes/flow-house-bangkok-surfen-e-11796/"],"coord_confidence":"medium"},{"id":183,"name":"Krudam Muay Thai School","g":"activity","category":"activity","area":"Thonglor / Sukhumvit 36","lat":13.7215,"lng":100.577,"vibe":"Beginner-friendly drop-in Muay Thai class: pad work with real trainers and a sweaty day-one ego check","tip":"~฿599 group session via NOW Muay Thai. Wrap rental available. Go mornings before the heat","price":"฿฿","hours":"","date_friendly":false,"night":false,"tags":["muay-thai","class","fitness"],"sources":["https://www.visitthailandtoday.com/top-lists/best-muay-thai-bangkok"],"coord_confidence":"low"},{"id":184,"name":"Bangkok Shooting Range","g":"activity","category":"activity","area":"Phaya Thai / Saphan Khwai","lat":13.788,"lng":100.5465,"vibe":"Fire real handguns, shotguns and rifles at an indoor range. Ages 20+","tip":"Bring your passport. Daytime only, 9am-5pm. Handgun packages from ~฿2,800","price":"฿฿฿฿","hours":"Daily 09:00-17:00","date_friendly":false,"night":false,"tags":["shooting","adventure","adrenaline"],"sources":["https://thesmartlocal.com/read/indoor-things-to-do-bangkok/amp/"],"coord_confidence":"low"},{"id":185,"name":"The Last Prison Escape Room","g":"activity","category":"activity","area":"Phaya Thai / Saphan Khwai","lat":13.786,"lng":100.545,"vibe":"Horror-themed escape rooms, including VR rooms. A screaming-together date","tip":"From ~฿980 for 2. Book ahead. Daytime hours only","price":"฿฿","hours":"Daily 10:00-19:00","date_friendly":true,"night":false,"tags":["escape-room","horror","vr","rainy-day"],"sources":["https://thesmartlocal.com/read/indoor-things-to-do-bangkok/amp/"],"coord_confidence":"low"},{"id":186,"name":"Harbor Island Rooftop Waterpark","g":"activity","category":"activity","area":"Bang Kapi","lat":13.7664,"lng":100.6429,"vibe":"Rooftop waterpark on The Mall Lifestore (opened 2025), with thrill slides and ziplines over the city","tip":"Adult play ticket ~฿670 for 6h, towel and locker included. Weekdays are less packed with kids","price":"฿฿","hours":"Daily ~10:00-20:00","date_friendly":true,"night":false,"tags":["waterpark","slides","new"],"sources":["https://thesmartlocal.com/read/harborland-waterpark-bangkok/","https://bangkokpost.com/thailand/pr/2962701/mega-harborland-opens-at-the-mall-bangkapi-"],"coord_confidence":"medium"},{"id":187,"name":"Topgolf Megacity Bangna","g":"activity","category":"activity","area":"Bang Na","lat":13.646,"lng":100.681,"vibe":"Topgolf bays with microchipped balls, cocktails and music. No golf skill needed","tip":"Book a bay for 2-6 people. Evenings have the best vibe. Next to Mega Bangna","price":"฿฿฿","hours":"Daily ~10:00-24:00","date_friendly":true,"night":true,"tags":["golf","bar","group","night"],"sources":["https://www.timeout.com/bangkok/things-to-do/sample-thai-craft-beer-between-golf-games-in-bangna","https://www.bkmagazine.com/city-living/topgolf-finally-opening-thailand-next-month/"],"coord_confidence":"medium"},{"id":188,"name":"Bradbury Loud Massage","g":"experience","category":"experience","area":"Ekkamai / Sukhumvit 61","lat":13.7255,"lng":100.586,"vibe":"Massage parlour that feels like a nightclub: DJ, live shows, and you get a massage in the middle of it","tip":"24h. Entry from ~฿350. Go after 10pm for the full chaos","price":"฿฿","hours":"24 hours","date_friendly":true,"night":true,"tags":["quirky","massage","nightlife","new"],"sources":["https://thesmartlocal.com/read/new-things-to-do-bangkok/","https://gothaitransport.com/new-things-to-do-in-bangkok/"],"coord_confidence":"medium"},{"id":189,"name":"Let's Relax Onsen & Spa Thonglor","g":"experience","category":"experience","area":"Thonglor","lat":13.7295,"lng":100.5805,"vibe":"Japanese-style onsen baths, sauna and hot-stone beds, open 24h. A slow date or recovery day","tip":"Onsen all-day pass from ~฿750. Late night is quietest","price":"฿฿","hours":"24 hours","date_friendly":true,"night":true,"tags":["onsen","spa","24h","rainy-day"],"sources":["https://thesmartlocal.com/read/indoor-things-to-do-bangkok/amp/"],"coord_confidence":"low"},{"id":190,"name":"Silom Thai Cooking School","g":"experience","category":"experience","area":"Silom","lat":13.7255,"lng":100.5225,"vibe":"Hands-on Thai cooking class with a wet-market tour first. You cook and eat 4-5 dishes","tip":"Book a day ahead. Morning, afternoon and evening slots, ~฿1,000-1,500. Evening class makes a good date","price":"฿฿฿","hours":"Classes ~9:00 / 13:40 / 18:00","date_friendly":true,"night":false,"tags":["class","cooking","food"],"sources":["https://www.byfood.com/experiences/bangkok-thai-cooking-class-and-vibrant-market-tour-in-silom-29091","https://www.trazy.com/experience/detail/thai-cooking-class-bangkok-silom"],"coord_confidence":"low"},{"id":191,"name":"Chao Phraya Express Boat (Orange Flag)","g":"experience","category":"experience","area":"Sathorn Pier / River","lat":13.7187,"lng":100.5135,"vibe":"Ride the river with locals past temples and palaces for pocket change. The cheapest sightseeing in Bangkok","tip":"Board at Sathorn Pier (BTS Saphan Taksin). Flat fare ~฿16. Ride to Tha Chang for Wat Arun views at sunset","price":"฿","hours":"~06:00-19:00","date_friendly":true,"night":false,"tags":["river","boat","cheap","sightseeing"],"sources":[],"coord_confidence":"high"},{"id":192,"name":"Khlong Saen Saep Canal Boat","g":"experience","category":"experience","area":"Pratunam","lat":13.7505,"lng":100.5405,"vibe":"Rough-and-tumble commuter canal boat with tarp splash guards and a jump-on-jump-off crew. Real Bangkok","tip":"From Pratunam pier west to Phan Fa (Old Town). ฿10-20. Avoid rush hour","price":"฿","hours":"~05:30-20:00","date_friendly":false,"night":false,"tags":["canal","boat","local","adventure"],"sources":[],"coord_confidence":"medium"},{"id":193,"name":"Woot Woot Vintage (Warehouse 30)","g":"shop","category":"shop","area":"Charoen Krung / Bang Rak","lat":13.729,"lng":100.515,"vibe":"Curated vintage and retro homeware inside the Warehouse 30 creative complex","tip":"Charoen Krung Soi 30. Pair with cafes on Charoen Krung and Talat Noi","price":"฿฿","hours":"","date_friendly":true,"night":false,"tags":["vintage","shopping","creative-district"],"sources":["https://www.timeout.com/bangkok/shopping/the-best-vintage-shops-in-bangkok"],"coord_confidence":"medium"},{"id":194,"name":"Fumiikii Tokyo","g":"shop","category":"shop","area":"Ari","lat":13.779,"lng":100.543,"vibe":"Japanese-curated vintage shop in hip Ari. Ari's cafes and street food are around the corner","tip":"Ari Soi 2, BTS Ari. Go late afternoon, then have dinner in the Ari sois","price":"฿฿","hours":"","date_friendly":true,"night":false,"tags":["vintage","japanese","ari"],"sources":["https://www.timeout.com/bangkok/shopping/the-best-vintage-shops-in-bangkok"],"coord_confidence":"low"},{"id":195,"name":"Treasure Factory Phra Khanong","g":"shop","category":"shop","area":"Phra Khanong","lat":13.7145,"lng":100.5935,"vibe":"Japanese second-hand megastore for branded clothes, gadgets and random Japan finds at low prices","tip":"Near BTS Phra Khanong. Several branches. Check the 'new arrivals' racks","price":"฿","hours":"","date_friendly":false,"night":false,"tags":["japanese","second-hand","bargains"],"sources":["https://www.timeout.com/bangkok/shopping/the-best-vintage-shops-in-bangkok"],"coord_confidence":"low"}];
